-- Replace the legacy exercise catalogue with the reviewed RepDB catalogue.
-- RepDB remains canonical in repdb/exercises_cleaned.json; this migration mirrors
-- searchable fields into public.exercises for planner/database consumers.
insert into public.equipment (slug,name,category) values
  ('bodyweight','No equipment','bodyweight'),('dumbbells','Dumbbells','free_weights'),
  ('kettlebell','Kettlebell','free_weights'),('resistance_band','Resistance bands','resistance'),
  ('loop_band','Loop bands','resistance'),('stationary_bike','Stationary bike','cardio'),
  ('stability_ball','Stability ball','accessories')
on conflict (slug) do update set name=excluded.name,category=excluded.category;

create temporary table repdb_catalogue_seed (id uuid,slug text primary key,name text,description text,instructions text,category text,movement_pattern text,difficulty text,impact_level text,is_outdoor boolean,is_active boolean,equipment_slug text) on commit drop;
insert into repdb_catalogue_seed (id,slug,name,description,instructions,category,movement_pattern,difficulty,impact_level,is_outdoor,is_active,equipment_slug) values
  ('30000000-0000-4000-8000-000000000001','archer-push-ups','Push-Ups Arquero','Una flexión ancha bajando hacia una mano mientras el brazo contrario permanece estirado, cargando un lado cada vez.','Colócate en posición de push-up amplia con los brazos extendidos. Bájate hacia una mano mientras mantienes el otro brazo extendido. Mantén el core apretado y el cuerpo en línea recta. Empuja de vuelta a la posición inicial. Alterna lados en cada repetición el número de veces deseado.','strength','compound','advanced',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000002','arnold-press','Press Arnold','Un press de hombros con mancuernas que rota las palmas durante el ascenso, dirigido al deltoides anterior y lateral.','Sostén un par de mancuernas a la altura de los hombros con las palmas mirando hacia ti. Empuja las mancuernas sobre la cabeza mientras rotas las palmas hacia adelante. Extiende los brazos por completo en la parte superior sin bloquear los codos. Invierte el movimiento y rota de vuelta a la posición inicial. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000003','ball-leg-curl','Curl de Piernas con Pelota de Estabilidad','Un curl de isquiotibiales con el propio peso usando una pelota de estabilidad, rodando los talones hacia los glúteos mientras se eleva la cadera.','Acuéstate boca arriba en el suelo con los talones y la parte inferior de las pantorrillas sobre la pelota de estabilidad y los brazos estirados para hacer equilibrio. Presiona con los talones para elevar las caderas formando una línea recta desde los hombros hasta los tobillos. Manteniendo las caderas arriba, flexiona las rodillas para rodar la pelota hacia los glúteos. Extiende las piernas de vuelta de forma controlada sin bajar las caderas. Completa todas las repeticiones, luego baja las caderas y sepárate de la pelota.','strength','isolation','intermediate',null,false,true,'stability_ball'),
  ('30000000-0000-4000-8000-000000000004','ball-pike','Pike con Pelota','Un ejercicio avanzado de core en el que las caderas se elevan mientras los pies ruedan una pelota suiza hacia el pecho.','Coloca las espinillas sobre una pelota suiza y las manos en el suelo en plancha alta. Activa el core y mantén las piernas rectas. Eleva las caderas, rodando la pelota hacia el pecho hasta formar una V invertida. Pausa brevemente arriba. Rueda la pelota de vuelta a la posición inicial de plancha.','strength','compound','advanced',null,false,true,'stability_ball'),
  ('30000000-0000-4000-8000-000000000005','band-pull-apart','Separación de Banda Elástica','Un ejercicio de alto volumen para el deltoides posterior y los retractores escapulares que se realiza separando una banda elástica a la altura de los hombros.','Párate sosteniendo una banda elástica ligera con ambas manos, brazos extendidos al frente a la altura de los hombros. Las manos comienzan a la anchura de los hombros, palmas mirando hacia abajo. Manteniendo los brazos extendidos, separa la banda llevando las manos hacia los lados. Termina con la banda tocando el pecho y los omóplatos juntos. Vuelve lentamente a la posición inicial y repite.','strength','isolation','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000006','banded-adductor-stretch','Estiramiento de Aductores con Banda','Un estiramiento tumbado que usa una banda para llevar una pierna estirada hacia el lado y alargar el aductor.','Acuéstate boca arriba con una banda en un pie. Eleva esa pierna y déjala abrir hacia el lado. Sujeta la banda para controlar cuánto baja la pierna. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000007','banded-ankle-stretch','Estiramiento de Tobillo con Banda','Un estiramiento sentado que usa una banda en el antepié para flexionar el tobillo y alargar la pantorrilla.','Siéntate con una pierna extendida y una banda en el antepié. Sujeta la banda con ambas manos. Tira para que los dedos se acerquen a la espinilla. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000008','banded-calf-stretch','Estiramiento de Pantorrilla con Banda','Un estiramiento tumbado que usa una banda en la planta del pie para flexionar el tobillo y alargar la pantorrilla.','Acuéstate boca arriba y pasa una banda por la planta de un pie. Eleva la pierna y mantenla bastante recta. Tira de la banda para que los dedos se acerquen a la espinilla. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000009','banded-chest-stretch','Estiramiento de Pecho con Banda','Un estiramiento de pie que abre el pecho sujetando una banda tras la espalda y separando los brazos.','Sujeta una banda con ambas manos tras la espalda. Estira los brazos y sepáralos. Eleva el pecho y junta los omóplatos. Mantén de 20 a 30 segundos, respirando de forma constante.','stretching','isolation','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000010','banded-clamshell','Almeja con Banda','Una abducción de cadera tipo almeja con una banda circular por encima de las rodillas, que aísla el glúteo medio.','Túmbate de lado con las caderas y rodillas flexionadas a unos 45 grados y los pies juntos uno sobre otro. Coloca una banda circular alrededor de ambas piernas por encima de las rodillas. Mantén los pies pegados y la pelvis estable; no rotes hacia atrás durante el movimiento. Abre la rodilla de arriba contra la banda, como una almeja al abrirse, hasta notar que el glúteo se activa. Haz una breve pausa arriba y baja de forma controlada hasta la posición inicial. Completa todas las repeticiones de un lado y luego cambia.','strength','isolation','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000011','banded-figure-4-stretch','Estiramiento Figura 4 con Banda','Un estiramiento de glúteos tumbado en posición de figura 4, usando una banda para acercar ambas piernas al pecho.','Acuéstate boca arriba y cruza un tobillo sobre el muslo opuesto. Pasa una banda por el muslo de apoyo. Lleva ambas piernas al pecho con la banda. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000012','banded-fire-hydrant','Hidrante de Fuego con Banda','Este ejercicio de aislamiento utiliza una banda de resistencia para fortalecer el glúteo medio y mayor, mejorando la abducción y estabilidad de la cadera.','Coloca una banda de resistencia justo por encima de tus rodillas y ponte en posición de cuadrupedia, manos bajo los hombros y rodillas bajo las caderas. Mantén tu core activado y la espalda recta, conservando una columna vertebral neutra durante todo el movimiento. Levanta lentamente una rodilla hacia un lado, manteniendo la rodilla flexionada a 90 grados, hasta que tu muslo esté paralelo al suelo. Sostén brevemente en la parte superior, contrayendo el glúteo, luego baja la pierna de forma controlada a la posición inicial. Completa todas las repeticiones de un lado antes de cambiar al otro lado.','strength','isolation','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000013','banded-glute-bridge','Puente de Glúteos con Banda','Un puente de glúteos con una banda circular por encima de las rodillas que suma tensión de abducción al empuje de cadera.','Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo a la anchura de los hombros. Coloca una banda circular alrededor de ambas piernas justo por encima de las rodillas. Presiona la zona lumbar contra el suelo y activa el core. Empuja con los talones y aprieta los glúteos para elevar las caderas en puente, manteniendo la tensión de la banda al empujar las rodillas hacia afuera. Arriba, el cuerpo forma una línea recta de los hombros a las rodillas. Haz una breve pausa. Baja de forma controlada hasta la posición inicial y repite el número de repeticiones recomendado.','strength','compound','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000014','banded-hamstring-stretch','Estiramiento de Isquiotibiales con Banda','Un estiramiento tumbado que usa una banda en el pie para acercar la pierna estirada al torso y alargar el isquiotibial.','Acuéstate boca arriba y pasa una banda por un pie. Eleva esa pierna recta, sujetando la banda con ambas manos. Tira suavemente de la banda para acercar la pierna. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000015','banded-it-band-stretch','Estiramiento de Banda Iliotibial con Banda','Un estiramiento tumbado que usa una banda para cruzar una pierna sobre el cuerpo y trabajar el muslo y la cadera externos.','Acuéstate boca arriba con una banda en un pie elevado. Sujeta la banda con la mano contraria. Lleva la pierna estirada cruzando el cuerpo hacia el suelo. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000016','banded-kneeling-hip-thrust','Empuje de Cadera Arrodillado con Banda','Este ejercicio fortalece los glúteos y los isquiotibiales al impulsar las caderas hacia adelante contra la resistencia de una banda desde una posición arrodillada.','Coloca una banda de bucle justo por encima de tus rodillas. Arrodíllate en el suelo con el torso erguido y las rodillas separadas al ancho de las caderas. Inclínate ligeramente hacia adelante desde las caderas, manteniendo la espalda recta y el core contraído. Inicia el movimiento apretando los glúteos, impulsando las caderas hacia adelante hasta que tu torso esté erguido. Aprieta los glúteos con fuerza en la parte superior, manteniendo la tensión en la banda. Invierte lentamente el movimiento, controlando la resistencia de la banda mientras regresas a la posición inicial.','strength','compound','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000017','banded-lat-stretch','Estiramiento de Dorsales con Banda','Un estiramiento de pie que alarga los dorsales al inclinarse hacia adelante sosteniendo una banda en tensión sobre la cabeza.','Sujeta una banda sobre la cabeza con ambas manos en tensión ligera. Inclínate desde las caderas con los brazos extendidos al frente. Deja caer el pecho para alargar los lados de la espalda. Mantén de 20 a 30 segundos, respirando de forma constante.','stretching','isolation','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000018','banded-lateral-walk','Caminata Lateral con Banda','Un desplazamiento lateral a pasos con una banda circular por encima de las rodillas o en los tobillos, que activa el glúteo medio.','Coloca una banda circular alrededor de las piernas por encima de las rodillas (o en los tobillos para una versión más difícil). Ponte en cuarto de sentadilla: pies a la anchura de los hombros, caderas atrás, pecho alto y rodillas alineadas con los pies. Da un paso lateral con un pie directamente hacia el lado contra la tensión de la banda. Acerca el pie de atrás hacia el de delante manteniendo la tensión de la banda en todo momento; no dejes que los pies se junten de golpe. Sigue dando pasos laterales en una dirección durante las repeticiones o la distancia indicada y luego invierte. Permanece abajo todo el rato; no te incorpores entre paso y paso.','strength','compound','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000019','banded-rear-delt-stretch','Estiramiento de Deltoides Posterior con Banda','Un estiramiento de pie para el hombro posterior llevando un brazo cruzado contra la tensión de la banda.','Pasa una banda por un brazo y sujeta el otro extremo. Lleva ese brazo en horizontal sobre el pecho. Usa la banda para profundizar el tirón suavemente. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000020','banded-shoulder-stretch','Estiramiento de Hombros con Banda','Un estiramiento de pie que abre los hombros y el pecho sujetando una banda tras la espalda, una mano arriba y otra abajo.','Sujeta una banda tras la espalda, una mano arriba y otra abajo. Mantén una tensión ligera en la banda. Abre el pecho y lleva los hombros suavemente atrás. Mantén de 20 a 30 segundos, respirando de forma constante.','stretching','isolation','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000021','banded-squat','Sentadilla con Banda','Una sentadilla con peso corporal y banda sobre las rodillas para enseñar a sacar las rodillas afuera.','Coloca una banda elástica justo sobre las rodillas. Pies a la anchura de los hombros, puntas ligeramente afuera. Empuja las rodillas hacia afuera contra la banda al bajar. Desciende hasta que los muslos queden paralelos o más abajo. Empuja con los talones para volver a subir.','strength','compound','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000022','banded-standing-curl','Curl de Pierna de Pie con Banda','Un curl femoral de pie con una banda elástica alrededor del tobillo, útil para viajes o como finalizador con poca carga para isquiotibiales.','Coloca una banda elástica alrededor de un tobillo y ancla el otro extremo bajo el pie de apoyo o en un punto fijo delante de ti. Mantente erguido, sujétate a algo si necesitas equilibrio, con ligera flexión en la pierna de apoyo. Sube el talón con la banda hacia el glúteo, manteniendo el muslo quieto. Contrae el isquiotibial arriba, luego baja con control hasta el estiramiento completo. Completa todas las repeticiones de un lado y cambia de pierna.','strength','isolation','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000023','banded-standing-hip-abduction','Abducción de Cadera de Pie con Banda','Este ejercicio de aislamiento trabaja el glúteo medio y mayor, mejorando la estabilidad y fuerza de la cadera al abducir la pierna contra la resistencia de la banda.','Coloca una banda elástica alrededor de tus tobillos o justo encima de tus rodillas. Ponte de pie con una ligera flexión de rodillas y activa tu core. Transfiere tu peso a una pierna, manteniendo el torso estable. Abduce lentamente la pierna libre hacia un lado, sintiendo la contracción del glúteo. Controla el movimiento mientras regresas la pierna a la posición inicial. Completa todas las repeticiones por lado antes de cambiar.','strength','isolation','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000024','banded-standing-hip-adduction','Aducción de Cadera de Pie con Banda','Una aducción de cadera de pie con banda elástica, aislando los aductores del muslo interno.','Ancla una banda elástica a un poste firme a la altura del tobillo. Pasa el bucle por la pierna que trabaja, orientada hacia el anclaje. Aléjate algunos pasos para que la banda quede tensa. Lleva la pierna que trabaja cruzando el cuerpo hacia la otra pierna. Regresa lentamente. Completa las repeticiones por lado y cambia.','strength','isolation','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000025','banded-sumo-walk','Caminata Sumo con Banda','Una caminata lateral en posición sumo con una banda alrededor de la parte baja de las piernas, que trabaja el glúteo medio y mayor.','Coloca una banda elástica alrededor de la parte baja de las piernas, justo por encima de los tobillos. Baja a una media sentadilla con los pies más anchos que los hombros. Da un paso lateral en posición ancha, manteniendo tensión en la banda. Acerca el pie de atrás solo en parte para que la banda siga tensa y sigue avanzando de lado la distancia indicada antes de cambiar de pierna guía. Permanece bajo — no te incorpores entre pasos.','strength','compound','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000026','banded-terminal-knee-extension','Extensión Terminal de Rodilla con Banda','Un ejercicio de aislamiento que extiende la rodilla contra la banda, usado para el VMO y rehabilitación.','Ancla una banda elástica a un poste firme a la altura de la rodilla. Pasa el bucle de modo que la banda quede detrás de una rodilla. Da un paso atrás para que la banda flexione ligeramente la rodilla. Extiende la rodilla completamente contra la banda, contrayendo el cuádriceps. Regresa lentamente. Repeticiones por lado y cambia.','strength','isolation','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000027','banded-triceps-stretch','Estiramiento de Tríceps con Banda','Un estiramiento de pie que alarga el tríceps llevando una mano tras la cabeza contra la tensión de la banda.','Sujeta una banda que baja por la espalda, con la mano de arriba tras la cabeza. Fija la mano de abajo en la zona lumbar. Baja la mano de arriba hasta sentir el tríceps estirarse. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000028','bear-crawl','Caminata del Oso','Un gateo en cuadrupedia sobre manos y puntas de los pies con las rodillas suspendidas justo por encima del suelo, que desarrolla la estabilidad del hombro y el control del core al desplazarse hacia adelante.','Empieza en cuadrupedia con las manos bajo los hombros y las rodillas bajo las caderas. Apoya las puntas de los pies y eleva las rodillas unos centímetros del suelo. Con la espalda plana y las caderas bajas, avanza juntos la mano derecha y el pie izquierdo. Luego mueve la mano izquierda y el pie derecho, gateando hacia adelante con ritmo controlado. Mantén el core firme y evita que las caderas se balanceen de lado a lado.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000029','bear-plank-hold','Plancha del Oso Isométrica','Un mantenimiento estático de core a cuatro apoyos en el que las rodillas flotan justo encima del suelo mientras la espalda permanece plana. Entrena el abdomen y los hombros para estabilizar el tronco y es un paso previo a la plancha completa.','Colócate a cuatro apoyos con las manos bajo los hombros y las rodillas bajo la cadera. Apoya las puntas de los pies en el suelo y contrae el abdomen para que la espalda quede plana. Empuja con las manos y levanta las rodillas unos 5 cm del suelo. Mantén la posición con la cadera nivelada y la cabeza alineada con la columna. Respira con regularidad y luego baja las rodillas para descansar.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000030','bent-over-db-row','Remo con Mancuernas Inclinado','Un remo inclinado a dos brazos con una mancuerna en cada mano, que trabaja la espalda y exige estabilidad.','Ponte de pie con los pies a la anchura de las caderas, sujetando una mancuerna en cada mano a los lados, con las palmas hacia dentro. Flexiona las caderas con la espalda recta hasta que el torso quede a unos 30–45 grados de la horizontal, con las mancuernas colgando justo debajo de los hombros. Activa el core y tira de ambas mancuernas hacia arriba y ligeramente atrás, llevando los codos por detrás de las costillas. Aprieta la parte alta de la espalda arriba, manteniendo los codos pegados. Baja de forma controlada hasta la posición inicial con los brazos completamente estirados. Repite el número de repeticiones recomendado.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000031','bicep-curl','Curl de Bíceps con Mancuernas','Un ejercicio de aislamiento que trabaja los bíceps.','Párate sosteniendo mancuernas a los lados, palmas hacia adelante. Sube las mancuernas hacia los hombros. Aprieta en la parte superior, luego baja de forma controlada. Repite.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000032','bicycle-crunch','Crunch de Bicicleta','Una variación dinámica del crunch que trabaja tanto el recto abdominal como los oblicuos.','Acuéstate boca arriba con las manos detrás de la cabeza y las piernas elevadas. Acerca una rodilla al pecho mientras rotas el torso para encontrarla con el codo opuesto. Extiende esa pierna mientras traes la otra rodilla hacia adentro. Continúa alternando en un movimiento de pedaleo. Repite.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000033','bird-dog','Bird-Dog','Un ejercicio de estabilidad del core que extiende el brazo y la pierna opuestos para trabajar los erectores espinales y el core profundo.','Comienza a cuatro patas con la columna en posición neutra. Extiende el brazo derecho hacia adelante y la pierna izquierda hacia atrás simultáneamente. Aguanta un momento, luego vuelve. Repite en el otro lado. Alterna.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000034','bird-dog-hold','Bird-Dog Isométrico','Un ejercicio isométrico de core a cuatro patas que extiende un brazo y la pierna contraria manteniendo la columna estable.','Comienza a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas. Extiende un brazo hacia adelante y la pierna opuesta hacia atrás. Mantén el core apretado y el cuerpo nivelado. Aguanta la posición sin rotar el torso. Mantén el tiempo indicado. Completa en un lado, luego cambia.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000035','boat-pose','Postura del Barco','Un equilibrio sentado sobre los isquiones con las piernas elevadas y el pecho alto: la forma de V carga los flexores de la cadera y toda la parte frontal del tronco.','Siéntate en el suelo con las rodillas flexionadas y los pies apoyados, las manos detrás de los muslos. Inclínate hacia atrás hasta equilibrarte justo por detrás de los isquiones y eleva el pecho para mantener la columna larga. Sube las espinillas hasta dejarlas paralelas al suelo y estira las piernas todo lo que la espalda pueda mantenerse plana. Extiende los brazos hacia delante junto a las piernas y mantén la posición durante el tiempo indicado. Baja los pies de forma controlada para terminar.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000036','bodyweight-calf-raise','Elevación de Talones con Peso Corporal','Una elevación de talones con el propio peso corporal, un ejercicio básico para fortalecer los gemelos.','Colócate de pie con los pies separados al ancho de las caderas sobre una superficie plana. Sube de puntillas lo más alto posible. Aprieta los gemelos en la parte superior. Baja los talones al suelo de forma controlada. Repite el número deseado de repeticiones.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000037','bodyweight-good-morning','Buenos Días con Peso Corporal','Una bisagra de cadera con el propio peso corporal que fortalece los erectores espinales y los isquiotibiales.','Colócate de pie con los pies separados al ancho de las caderas y las manos detrás de la cabeza. Mantén una ligera flexión en las rodillas y contrae el core. Bisagra en las caderas y baja el torso hasta quedar casi paralelo al suelo. Impulsa las caderas hacia adelante para volver a la posición erguida. Repite el número deseado de repeticiones.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000038','bodyweight-lateral-raise','Elevación Lateral con Peso Corporal','Un movimiento de aislamiento de hombros sin equipamiento para desarrollar el ancho del deltoides lateral.','Párate erguido con los brazos colgando a los lados. Levanta ambos brazos hacia los lados con un ligero codo doblado hasta la altura de los hombros. Haz una pausa breve arriba. Baja lentamente a la posición inicial. Repite el número de repeticiones deseado.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000039','bodyweight-overhead-press','Press por Encima de la Cabeza con Peso Corporal','Un press por encima de la cabeza de pie y sin carga: los brazos empujan desde los hombros hasta quedar estirados sobre la cabeza, practicando el patrón de empuje de hombros y tríceps sin ningún material.','Ponte de pie con los pies a la anchura de las caderas y las manos en puños relajados a la altura de los hombros, palmas hacia delante y codos bajo las muñecas. Activa el core y aprieta los glúteos para que las costillas no se abran. Empuja ambos brazos hacia arriba hasta extender del todo los codos, con los brazos junto a las orejas. Baja las manos con control hasta la altura de los hombros. Repite el número de repeticiones deseado.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000040','bodyweight-reverse-lunge','Zancada Inversa con Peso Corporal','Una variante de zancada usando solo el peso corporal, dando un paso hacia atrás para mayor estabilidad de rodilla que una zancada hacia adelante.','Ponte de pie con los pies separados a la altura de las caderas. Da un paso hacia atrás con una pierna y baja la rodilla hacia el suelo. Baja hasta que tu muslo delantero quede paralelo al suelo. Empuja a través del talón delantero para volver a la posición de pie. Repite con ambas piernas.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000041','bodyweight-squat','Sentadilla con Peso Corporal','Una sentadilla con el propio peso corporal, apta para principiantes, que desarrolla los glúteos y los cuádriceps.','Colócate de pie con los pies separados al ancho de los hombros y los brazos extendidos al frente. Siéntate hacia atrás y hacia abajo flexionando caderas y rodillas. Baja hasta que los muslos queden paralelos al suelo. Empuja con los talones para volver a la posición de pie. Repite el número deseado de repeticiones.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000042','bow-pose','Postura del Arco','Una extensión en decúbito prono: las manos sujetan los tobillos y las piernas empujan contra ellas, elevando pecho y muslos del suelo y activando toda la cadena posterior.','Túmbate boca abajo con los brazos junto al cuerpo y la frente apoyada en la esterilla. Flexiona las rodillas y agarra la parte externa de ambos tobillos. Empuja las espinillas contra las manos para que el pecho y los muslos se despeguen del suelo. Mantén la posición elevada durante el tiempo indicado, con el cuello largo y la mirada al frente. Suelta los tobillos y baja de forma controlada.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000043','burpees','Burpees','Un ejercicio de acondicionamiento de cuerpo completo que combina sentadilla, plank, flexión y salto.','Mantente en pie con los pies a la anchura de los hombros. Baja en sentadilla y apoya las manos en el suelo delante de ti. Salta o lleva los pies atrás a la posición de plank y haz una flexión. Salta o lleva los pies adelante hasta las manos. Levántate y salta explosivamente con los brazos arriba.','cardio','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000044','butterfly-stretch','Estiramiento de Mariposa','Un estiramiento sentado para los aductores, juntando las plantas de los pies con las rodillas caídas hacia afuera.','Siéntate erguido y junta las plantas de los pies. Deja caer las rodillas hacia el suelo. Sujeta los pies y mantente erguido. Mantén de 20 a 30 segundos, respirando de forma constante.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000045','cat-cow','Gato-Vaca','Un flujo a cuatro apoyos que alterna entre redondear la columna hacia el techo y dejarla descender mientras el pecho se abre, moviendo cada segmento de la espalda por su recorrido.','Colócate a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas. Exhala y redondea la columna hacia el techo, metiendo el coxis y dejando caer la cabeza. Inhala e inviértelo: deja descender el abdomen, eleva el pecho y el coxis y mira ligeramente al frente. Alterna entre ambas formas despacio, una respiración por posición. Termina en columna neutra y siéntate sobre los talones.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000046','cat-stretch','Estiramiento del Gato','Un estiramiento de rodillas que redondea la columna hacia arriba para alargar los músculos de la espalda.','Empieza en cuadrupedia, manos bajo los hombros y rodillas bajo las caderas. Redondea la columna hacia el techo. Lleva el mentón hacia el pecho. Mantén de 20 a 30 segundos, respirando de forma constante.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000047','chair-pose','Postura de la Silla','Un sostén de pie con las caderas hacia atrás y los brazos arriba, donde el cuádriceps y la espalda alta trabajan de forma isométrica contra el peso corporal.','Ponte de pie con los pies juntos o a la anchura de las caderas y el peso en los talones. Flexiona las rodillas y lleva las caderas atrás como si fueras a sentarte en una silla. Eleva los brazos junto a las orejas sin dejar que las costillas se abran. Mantén la posición durante el tiempo indicado, con el pecho alto y las rodillas siguiendo la línea de los pies. Empuja con los talones para volver a ponerte de pie.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000048','childs-pose','Postura del Niño','Un estiramiento de descanso de rodillas que alarga los dorsales, la zona lumbar y los hombros con los brazos al frente.','Arrodíllate y lleva la cadera hacia los talones. Inclina el torso hacia adelante sobre los muslos. Extiende ambos brazos largos sobre el suelo al frente. Mantén de 20 a 30 segundos, respirando de forma constante.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000049','chin-tuck-hold','Retracción de Mentón Sostenida','Un ejercicio estático de cuello que retrae la cabeza hacia atrás para fortalecer los flexores profundos del cuello y contrarrestar la postura de cabeza adelantada.','Ponte de pie o siéntate erguido con los hombros relajados. Lleva el mentón recto hacia atrás, creando una papada. Mantén la cabeza nivelada sin inclinarla. Mantén la posición durante el tiempo deseado. Suelta y repite durante varias series.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000050','clamshells','Almejas','Un ejercicio de abducción de cadera, realizado tumbado de lado, que activa el glúteo medio sin material adicional.','Túmbate de lado con las rodillas dobladas y apiladas una sobre la otra. Mantén los pies juntos y las caderas alineadas. Abre la rodilla superior hacia el techo sin rotar las caderas. Aprieta el glúteo externo en la posición superior. Baja de forma controlada. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000051','clamshells-hold','Almejas Isométricas','La posición final de la almeja mantenida en el tiempo: tumbado de lado con las rodillas flexionadas y apiladas, la rodilla superior se abre y la pelvis se mantiene firme, de modo que el glúteo medio trabaja de forma isométrica en lugar de por repeticiones.','Túmbate de lado con las caderas y las rodillas flexionadas unos 45 y 90 grados, los talones juntos y las rodillas apiladas. Alinea los hombros y las caderas en vertical y aprieta el tronco para que la pelvis no ruede hacia atrás. Abre la rodilla superior todo lo que puedas sin que la pelvis rote, manteniendo los talones en contacto. Mantén esa posición abierta durante el tiempo indicado, respirando con normalidad. Baja la rodilla de forma controlada y repite del otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000052','clap-push-ups','Flexiones con Palmada','Una flexión pliométrica explosiva que desarrolla la potencia del pecho y las fibras musculares de contracción rápida.','Comienza en la posición estándar de flexión. Baja el pecho hacia el suelo. Empuja hacia arriba de forma explosiva para que las manos despeguen del suelo. Da una palmada y aterriza suavemente, volviendo a la posición inicial. Repite.','strength','compound','advanced',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000053','close-grip-push-ups','Flexiones con Agarre Cerrado','Una variante de flexión con las manos juntas que enfatiza el tríceps.','Adopta una posición de flexión con las manos directamente bajo los hombros. Mantén los codos pegados a las costillas. Baja el pecho hacia el suelo. Empuja de vuelta a la posición inicial. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000054','cobra-stretch','Estiramiento de la Cobra','Una extensión boca abajo que estira los abdominales y la parte frontal del torso al elevar el pecho.','Acuéstate boca abajo con las manos bajo los hombros. Empuja con las manos para levantar el pecho del suelo. Mantén caderas y piernas en el suelo, con los hombros relajados. Mantén de 20 a 30 segundos, respirando de forma constante.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000055','cocoons','Cocoons','Un ejercicio abdominal dinámico que combina un encogimiento de rodillas con un crunch desde una posición extendida boca arriba.','Túmbate boca arriba con los brazos extendidos sobre la cabeza; manos y pies ligeramente elevados. Lleva las rodillas al pecho y balancea los brazos hacia adelante en un crunch simultáneamente. Intenta tocar las espinillas con las manos en el punto máximo. Extiende brazos y piernas de forma controlada sin tocar el suelo. Repite el movimiento durante las repeticiones indicadas.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000056','cossack-squat','Sentadilla cosaca','Una sentadilla lateral de base amplia que hunde el cuerpo profundamente sobre una pierna flexionada mientras la otra permanece recta, entrenando fuerza unilateral, movilidad de cadera y flexibilidad de aductores.','Ponte en una postura amplia con las puntas de los pies ligeramente hacia afuera. Desplaza el peso hacia un lado, flexiona esa rodilla y húndete en una sentadilla profunda. Mantén la pierna contraria recta, con el talón en el suelo y los dedos hacia arriba. Baja tanto como te permita tu movilidad, manteniendo el pecho erguido. Empuja con la pierna flexionada para volver al centro y repite hacia el otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000057','cow-face-pose','Postura de la Cara de Vaca','Una postura sentada con las rodillas apiladas y los brazos enlazados a la espalda, que estira la cadera externa de un lado y los hombros en direcciones opuestas.','Siéntate en el suelo y cruza una rodilla justo encima de la otra para que queden apiladas en la línea media. Camina los pies hacia las caderas y apoya ambos isquiones por igual. Sube el brazo del lado de la rodilla superior y flexiónalo por detrás de la cabeza; sube el otro brazo por la espalda hasta engancharlos. Mantén la posición durante el tiempo indicado, con el pecho abierto y la columna larga. Suelta y repite con la otra pierna y el otro brazo arriba.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000058','crab-dips','Fondos de Cangrejo','Un ejercicio de tríceps en el suelo desde la mesa invertida: con las manos detrás de las caderas y el tronco elevado, los codos se flexionan y estiran para subir y bajar el cuerpo.','Siéntate con las rodillas flexionadas, los pies apoyados y las manos en el suelo detrás de ti, con los dedos hacia los talones. Empuja con manos y pies y eleva las caderas hasta que el tronco quede a la altura de las rodillas. Flexiona los codos hacia atrás para bajar las caderas hacia el suelo sin sentarte. Empuja de nuevo hasta estirar los brazos, manteniendo las caderas elevadas. Repite las veces indicadas y baja las caderas para terminar.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000059','crescent-lunge','Zancada Alta','Un sostén en paso largo con el talón trasero elevado y los brazos arriba, que carga la pierna delantera mientras la cadera trasera se mantiene larga.','Adelanta un pie a un paso largo con el talón trasero elevado y los dedos apuntando al frente. Flexiona la rodilla delantera unos noventa grados para que quede sobre el tobillo. Lleva la cadera trasera hacia delante hasta que ambas apunten al frente de la esterilla y eleva los brazos. Mantén la posición durante el tiempo indicado, con las costillas cerradas y la pierna trasera estirada. Junta los pies y repite del otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000060','cross-body-crunch','Crunch Cruzado','Un crunch de oblicuos en el suelo que acerca el codo y la rodilla opuestos entre sí, trabajando los oblicuos y el recto abdominal juntos.','Túmbate boca arriba en el suelo con las rodillas dobladas y las manos ligeramente detrás de las orejas. Contrae y rota llevando el codo derecho hacia la rodilla izquierda mientras la rodilla sube. Regresa a la posición inicial de forma controlada. Repite del otro lado, alternando en cada repetición.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000061','cross-body-hammer-curl','Curl Martillo Cruzado','Un curl con agarre neutro que lleva la mancuerna cruzando el cuerpo hacia el hombro opuesto, enfatizando el braquial y los antebrazos.','De pie, sujeta una mancuerna en cada mano con agarre neutro. Sube una mancuerna cruzando el cuerpo hacia el hombro opuesto. Mantén el codo fijo a tu costado. Baja de forma controlada y repite del otro lado. Continúa alternando el número de repeticiones deseado.','strength','isolation','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000062','cross-body-shoulder-stretch','Estiramiento de Hombro Cruzado','Un estiramiento de pie para el hombro posterior llevando un brazo en horizontal sobre el pecho.','Párate erguido y cruza un brazo estirado sobre el pecho. Engancha el otro antebrazo por debajo. Tira suavemente del brazo hacia el pecho. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000063','crow-pose','Postura del Cuervo','Un equilibrio sobre brazos: las rodillas descansan en la parte posterior de los brazos y los pies se elevan, sostenidos por hombros, brazos y tronco.','Ponte en cuclillas con los pies juntos y apoya las palmas en el suelo a la anchura de los hombros. Flexiona los codos hacia atrás y coloca las rodillas altas sobre la parte posterior de los brazos. Desplaza el peso hacia delante sobre las manos hasta que los pies se despeguen del suelo. Mantén el equilibrio durante el tiempo indicado, con la espalda alta redondeada y la mirada algo adelante. Baja los pies de forma controlada.','strength','compound','advanced',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000064','crunches','Crunches','Un ejercicio abdominal básico enfocado en el recto abdominal.','Túmbate boca arriba con las rodillas dobladas y las manos detrás de la cabeza. Enrolla el tronco superior hacia las rodillas levantando los omóplatos del suelo. Aprieta el abdomen en la posición superior. Baja con control. Repite.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000065','dancer-pose','Postura del Bailarín','Un equilibrio de pie sobre una pierna en el que el pie libre se sujeta por detrás y empuja hacia atrás, combinando extensión de columna y sostén unipodal.','Ponte de pie y pasa el peso a un pie, con esa rodilla ligeramente flexionada. Flexiona la otra rodilla y agarra la cara interna de ese tobillo por detrás. Empuja el pie elevado contra la mano y estira el brazo contrario hacia delante mientras el pecho sube. Mantén la forma durante el tiempo indicado, con la cadera de apoyo nivelada y la mirada fija. Suelta el pie y repite del otro lado.','strength','compound','advanced',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000066','db-kickstand-deadlift','Peso Muerto Kickstand con Mancuerna','Un movimiento de bisagra de cadera en postura escalonada con una mancuerna que carga la pierna delantera mientras el pie trasero ofrece apoyo ligero.','Coloca un pie detrás de modo que solo los dedos rocen el suelo. Sostén una mancuerna en la mano del lado del pie trasero. Bisagra en la cadera bajando la mancuerna hacia la espinilla con la espalda recta. Mantén la mayor parte del peso en el pie delantero. Empuja con el talón delantero para volver a la posición inicial. Completa todas las repeticiones antes de cambiar de lado.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000067','db-lunge','Zancada con Mancuernas','Un ejercicio unilateral de tren inferior con mancuernas que trabaja los cuádriceps y los glúteos mediante un paso adelante.','De pie, sujeta mancuernas a los costados. Da un paso adelante con un pie y baja la rodilla trasera hacia el suelo. Empuja con el pie delantero para volver. Alterna las piernas. Repite.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000068','db-overhead-carry','Paseo con Mancuerna sobre la Cabeza','Un paseo cargado con una sola mancuerna bloqueada por encima del hombro, que exige estabilidad de hombro y un tronco erguido en cada paso.','Lleva una mancuerna, en cargada o press, hasta quedar bloqueada justo encima del hombro. Estira el brazo del todo, con el codo bloqueado y el bíceps cerca de la oreja. Lleva las costillas hacia abajo en lugar de arquear la zona lumbar para sostener el peso arriba. Camina hacia delante con zancadas controladas, manteniendo la mancuerna alineada sobre hombro y cadera. Mira al frente — echar la cabeza atrás para vigilar el peso arrastra contigo toda la postura. Carga la distancia deseada, baja de forma controlada y repite con el otro brazo.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000069','db-preacher-curl','Curl Predicador con Mancuernas','Un curl de aislamiento de bíceps con una mancuerna en cada mano y la parte superior de los brazos apoyada en un banco predicador. El pad fija los codos en su sitio, así que el bíceps hace el trabajo casi sin balanceo.','Ajusta el asiento para que las axilas descansen contra la parte superior del pad y la parte superior de los brazos quede plana sobre él. Sujeta una mancuerna en cada mano con agarre supino y deja que los brazos cuelguen a lo largo del pad. Sube ambas mancuernas hacia los hombros sin despegar los codos del pad. Aprieta brevemente los bíceps arriba. Baja las mancuernas despacio hasta que los brazos queden casi extendidos y repite.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000070','db-reverse-curl','Curl Inverso con Mancuernas','Una variación del curl con agarre prono que trabaja el braquial y los extensores del antebrazo.','Sujeta las mancuernas con agarre prono a los costados. Súbelas hasta la altura de los hombros. Baja de forma controlada. Repite.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000071','db-shrug','Encogimiento de Hombros con Mancuernas','Un encogimiento de hombros con mancuernas que trabaja el trapecio superior para dar volumen al cuello y la espalda alta.','De pie, sujeta mancuernas a los costados. Encoge los hombros hacia arriba lo más alto posible. Mantén brevemente y luego baja. Repite.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000072','db-somersault-squat','Sentadilla Somersault con Mancuerna','Una sentadilla unilateral con alcance y mancuerna, que añade rotación y movilidad de hombro al patrón de sentadilla.','Pies a la anchura de los hombros, sostén una mancuerna en una mano a la altura del hombro. Baja en sentadilla mientras llevas la mancuerna al frente y cruzando el cuerpo. Alcanza el punto bajo con la mancuerna extendida pasando la rodilla opuesta. Empuja con los talones para subir, regresando la mancuerna al hombro. Repeticiones por lado, luego cambia.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000073','db-squat','Sentadilla con Mancuernas','Una sentadilla cargada con una mancuerna en cada mano a los costados, accesible sin barra.','Pies a la anchura de los hombros, una mancuerna en cada mano a los lados. Activa el core y mantén el pecho arriba. Baja en sentadilla flexionando caderas y rodillas. Desciende hasta que los muslos queden paralelos o más abajo. Empuja con los talones para volver a subir.','strength','compound','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000074','db-sumo-squat','Sentadilla Sumo con Mancuernas','Una sentadilla de pies anchos con mancuernas sujetadas a los lados, que enfatiza la cara interna de los muslos y los glúteos.','Ponte de pie con los pies más anchos que los hombros y las puntas giradas hacia afuera unos 30 grados. Sujeta una mancuerna en cada mano a los lados. Activa el core y mantén el pecho alto. Flexiona caderas y rodillas para bajar recto en una sentadilla profunda. Empuja con los talones para volver a ponerte de pie. Repite el número de repeticiones deseado.','strength','compound','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000075','db-svend-press','Press Svend con Mancuernas','Un ejercicio de pecho de pie presionando dos mancuernas entre sí frente al cuerpo, donde la presión hacia dentro mantiene los pectorales en tensión constante.','De pie, junta dos mancuernas horizontalmente a la altura del pecho. Mantén la presión hacia adentro sobre las mancuernas todo el tiempo. Empuja las mancuernas al frente hasta que los brazos queden casi estirados. Tíralas de regreso al pecho con control. Repite el número de repeticiones indicado.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000076','dead-bug','Dead Bug','Un ejercicio de core en decúbito supino que coordina la extensión de extremidades opuestas para entrenar la estabilidad del core profundo.','Túmbate boca arriba con los brazos extendidos hacia el techo y las rodillas a 90 grados. Baja el brazo derecho y la pierna izquierda hacia el suelo manteniendo la zona lumbar presionada contra el suelo. Regresa a la posición inicial. Repite del otro lado. Alterna.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000077','dead-bug-hold','Dead Bug Isométrico','La posición extendida del dead bug mantenida en el tiempo: tumbado boca arriba con un brazo por encima de la cabeza y la pierna contraria estirada justo por encima del suelo, con la zona lumbar pegada al suelo.','Túmbate boca arriba con los brazos apuntando al techo y las caderas y rodillas flexionadas a 90 grados. Presiona la zona lumbar contra el suelo y mantenla ahí durante toda la serie. Extiende un brazo por encima de la cabeza y estira la pierna contraria hasta que ambos queden suspendidos justo sobre el suelo. Mantén esa posición extendida durante el tiempo indicado, sin que las costillas se abran ni la espalda se arquee. Vuelve al inicio y repite con el otro brazo y la otra pierna.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000078','deep-squat-hold','Sentadilla Profunda Isométrica','Una sentadilla estática en la posición más baja, con la cadera por debajo de las rodillas, los talones apoyados y las manos juntas delante del pecho. Desarrolla resistencia y movilidad en caderas, rodillas y tobillos.','Colócate de pie con los pies algo más abiertos que los hombros y las puntas hacia fuera. Junta las manos delante del pecho y baja la cadera entre los talones. Desciende hasta que la cadera quede por debajo de las rodillas mientras los talones permanecen apoyados en el suelo. Mantén el pecho erguido y presiona los codos contra las rodillas para empujarlas hacia fuera. Mantén la posición respirando con regularidad y luego ponte de pie.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000079','diamond-push-ups','Flexiones en Diamante','Una flexión con las manos juntas formando un diamante con pulgares e índices, trasladando el énfasis a los tríceps.','Adopta la posición de flexión con las manos juntas formando un diamante. Mantén los codos pegados a los costados. Baja el pecho hacia las manos. Empuja hacia arriba para extender los brazos. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000080','dolphin-pose','Postura del Delfín','Una V invertida sostenida sobre los antebrazos: las caderas suben hacia el techo mientras los hombros asumen la carga, la preparación estándar para las inversiones sobre antebrazos.','Arrodíllate y apoya los antebrazos en el suelo a la anchura de los hombros, con los codos bajo los hombros. Mete los dedos de los pies y eleva las caderas arriba y atrás hasta formar una V invertida. Presiona los antebrazos contra el suelo y aleja los hombros de las orejas; los talones pueden quedar altos. Mantén la posición durante el tiempo indicado, con el cuello relajado entre los brazos. Baja las rodillas al suelo para salir.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000081','doorway-chest-stretch','Estiramiento de Pecho en el Marco','Un estiramiento de brazos abiertos que alarga el pecho y los hombros frontales al llevar los brazos atrás.','Párate erguido y sube los brazos en posición de portería. Flexiona los codos noventa grados, antebrazos verticales. Lleva los codos atrás y junta los omóplatos. Mantén de 20 a 30 segundos, respirando de forma constante.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000082','double-db-kickstand-deadlift','Peso Muerto Kickstand con Doble Mancuerna','Un movimiento de bisagra de cadera en postura escalonada con dos mancuernas que carga principalmente la pierna delantera con el pie trasero como apoyo de equilibrio.','Coloca un pie detrás de modo que solo los dedos toquen el suelo. Sostén una mancuerna en cada mano a la altura de la cadera. Bisagra en la cadera bajando ambas mancuernas hacia la espinilla con la espalda recta. Mantén la mayor parte del peso en el pie delantero. Empuja con el talón delantero para volver a posición inicial. Cambia de lado.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000083','double-db-overhead-carry','Paseo con Dos Mancuernas sobre la Cabeza','Un paseo cargado con una mancuerna bloqueada sobre cada hombro, que duplica la carga por encima de la cabeza y elimina el brazo libre que de otro modo te ayudaría a equilibrarte.','Lleva una mancuerna, en cargada o press, hasta el bloqueo sobre cada hombro. Estira ambos codos del todo y sigue empujando hacia arriba contra los pesos para que los hombros se mantengan activos, sin dejar que las mancuernas se hundan sobre ellos. Aprieta fuerte y mantén las costillas abajo — con los dos brazos arriba la tentación de arquearse es mucho mayor. Camina hacia delante con zancadas cortas y deliberadas, manteniendo ambas mancuernas alineadas sobre los hombros. Sigue respirando de forma superficial y constante en vez de aguantar el aire todo el recorrido. Carga la distancia deseada y baja después ambos pesos de forma controlada.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000084','downward-dog','Perro Boca Abajo','Un estiramiento en V invertida que alarga a la vez isquiotibiales, pantorrillas, hombros y espalda.','Empieza en cuadrupedia con las manos algo por delante de los hombros. Apoya los dedos de los pies y eleva la cadera hacia arriba y atrás. Estira las piernas y lleva los talones hacia el suelo. Mantén de 20 a 30 segundos, respirando de forma constante.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000085','downward-dog-knee-tuck','Rodilla al Pecho en Perro Boca Abajo','Un ejercicio dinámico de core sostenido en perro boca abajo: las caderas se mantienen altas mientras una rodilla se lleva bajo el pecho y vuelve al inicio, alternando lados. Los hombros sostienen toda la serie, de modo que el tronco trabaja sin la posición baja de cadera de una plancha.','Colócate en perro boca abajo con las manos a la anchura de los hombros y las caderas altas. Empuja el suelo y aprieta el tronco para que la zona lumbar siga larga. Lleva una rodilla hacia el pecho, redondeando ligeramente la espalda alta al entrar. Extiende la pierna de vuelta a la posición inicial de forma controlada. Repite con la otra pierna y sigue alternando las veces indicadas.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000086','downward-dog-to-knee-drive','Rodilla al Codo desde Perro de Tres Patas','Desde el perro de tres patas, la pierna elevada se pliega hacia delante para llevar la rodilla hacia el codo o la nariz y vuelve a extenderse. Los hombros sostienen la posición y el tronco hace el plegado, un lado cada vez.','Colócate en perro boca abajo y eleva una pierna por detrás a perro de tres patas. Presiona ambas manos contra el suelo y desplaza el peso ligeramente hacia delante. Redondea la espalda alta y lleva esa rodilla hacia el codo o la nariz. Extiende la pierna de vuelta arriba de forma controlada. Termina las repeticiones de ese lado y cambia.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000087','downward-dog-to-low-lunge','Perro Boca Abajo a Zancada Baja','El paso al frente clásico: desde el perro boca abajo un pie viaja entre las manos hasta una zancada baja y regresa. Abre el flexor de la cadera de la pierna trasera y ensaya la transición que aparece en toda práctica de flujo.','Empieza en perro boca abajo con las manos a la anchura de los hombros. Desplaza el peso hacia delante y lleva un pie entre las manos. Baja la rodilla trasera al suelo y hunde las caderas en una zancada baja. Empuja con las manos, levanta la rodilla trasera y devuelve el pie delantero al perro boca abajo. Repite del otro lado y sigue alternando.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000088','downward-dog-to-plank','Perro Boca Abajo a Plancha','Una transición en movimiento entre el perro boca abajo y la plancha alta: las caderas viajan de arriba a la horizontal y de vuelta, de modo que hombros y tronco trabajan en recorrido completo en lugar de sostener una posición.','Colócate en perro boca abajo con las caderas altas y las manos a la anchura de los hombros. Desplaza el peso hacia delante y baja las caderas hasta formar una línea recta en plancha alta. Sostén la plancha un instante con las costillas cerradas y los glúteos activos. Empuja el suelo y eleva las caderas de vuelta al perro boca abajo. Sigue alternando las veces indicadas.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000089','downward-dog-to-upward-dog','Perro Boca Abajo a Perro Boca Arriba','La transición del vinyasa: el cuerpo viaja desde el perro boca abajo hacia delante al perro boca arriba y de vuelta, alternando entre una V invertida cargada en los hombros y una extensión con el pecho abierto.','Empieza en perro boca abajo con las caderas altas y las manos a la anchura de los hombros. Desplázate hacia delante pasando por la plancha, baja un poco y lleva el pecho al frente hasta el perro boca arriba con los muslos despegados. Lleva los hombros atrás y abajo y mantén el cuello largo. Mete los dedos de los pies, empuja el suelo y eleva las caderas de vuelta al perro boca abajo. Sigue moviéndote entre ambas posiciones las veces indicadas.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000090','dumbbell-calf-raise','Elevación de Talones con Mancuernas','Una elevación de talones con mancuernas sobre una superficie elevada que trabaja gemelos y sóleo en rango completo.','Ponte de pie sujetando una mancuerna en cada mano a los costados. Coloca las puntas de los pies sobre una superficie elevada con los talones colgando. Empuja a través de las puntas de los pies para subir los talones lo más alto posible. Aprieta los gemelos en la parte superior del movimiento. Baja los talones por debajo de la plataforma para estirar los gemelos. Repite el número de repeticiones deseado.','strength','isolation','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000091','dumbbell-clean-and-press','Clean and Press con Mancuernas','Un ejercicio de potencia de cuerpo completo en el que dos mancuernas se suben en clean hasta los hombros y luego se empujan por encima de la cabeza en una secuencia fluida. Desarrolla potencia explosiva de cadera, además de hombros y tríceps fuertes.','Colócate de pie con los pies a la anchura de las caderas y una mancuerna en cada mano, colgando a los costados. Haz una bisagra de cadera y flexiona ligeramente las rodillas para bajar las mancuernas justo por debajo de las rodillas. Extiende las caderas y las rodillas de forma explosiva y encoge los hombros para subir las mancuernas hasta los hombros, recibiéndolas con los codos hacia delante. Flexiona ligeramente las rodillas y empuja las mancuernas en vertical sobre la cabeza hasta bloquear los brazos. Baja las mancuernas de nuevo a los hombros y luego a los costados, de forma controlada. Repite el número de repeticiones deseado.','olympic','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000092','dumbbell-curl-and-press','Curl y Press con Mancuernas','Un movimiento compuesto de pie que une un curl con mancuernas y un press por encima de la cabeza: las mancuernas se suben en curl hasta los hombros y luego se empujan en vertical sobre la cabeza antes de bajarlas. Trabaja los bíceps y los hombros en una sola repetición fluida.','Colócate de pie con los pies a la anchura de las caderas, sujetando una mancuerna en cada mano a los lados del cuerpo con las palmas hacia delante. Sube ambas mancuernas en curl hasta los hombros, manteniendo los codos pegados al cuerpo. Empuja las mancuernas por encima de la cabeza hasta extender del todo los brazos. Baja las mancuernas de nuevo a los hombros de forma controlada. Bájalas a los costados con un curl inverso controlado y repite.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000093','dumbbell-deadlift','Peso Muerto con Mancuernas','Un peso muerto con mancuernas que fortalece la cadena posterior mediante un patrón de bisagra de cadera.','Ponte de pie con las mancuernas frente a los muslos y los pies al ancho de las caderas. Inclínate desde las caderas y baja las mancuernas a lo largo de las piernas con la espalda recta. Mantén las mancuernas cerca de las espinillas durante el descenso. Empuja a través de los talones para volver a la posición de pie. Extiende completamente las caderas en la parte superior sin hiperlordosis lumbar. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000094','dumbbell-face-pull','Face Pull con Mancuernas','Un ejercicio para el deltoides posterior y la espalda alta, tirando de mancuernas hacia la cara con los codos muy abiertos.','Ponte de pie o siéntate sosteniendo una mancuerna en cada mano con los brazos extendidos hacia adelante. Flexiona los codos y tira de las mancuernas hacia la cara. Abre los codos hasta la altura de los hombros. Contrae el deltoides posterior y la espalda alta en el punto máximo. Baja las mancuernas con control. Repite el número de repeticiones deseado.','strength','isolation','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000095','dumbbell-farmers-walk','Caminata del Granjero con Mancuernas','Este ejercicio de cuerpo completo implica caminar sosteniendo mancuernas pesadas, desarrollando eficazmente la fuerza de agarre, la estabilidad del core y la resistencia muscular general.','Párate erguido con una mancuerna en cada mano, los brazos extendidos a los lados. Retrae tus escápulas y activa tu core, manteniendo una columna vertebral neutra. Camina lenta y deliberadamente por una distancia o duración establecida, dando pasos cortos y controlados. Mantén el pecho erguido y evita inclinarte hacia un lado mientras caminas. Concéntrate en mantener una postura fuerte y estable durante todo el movimiento.','strength','compound','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000096','dumbbell-floor-press','Press de Suelo con Mancuernas','Un press con mancuernas realizado tumbado en el suelo, que limita el rango de movimiento para un press más amigable con las articulaciones.','Túmbate en el suelo con una mancuerna en cada mano a la altura del pecho. Empuja las mancuernas hacia arriba hasta que los brazos queden extendidos. Baja de forma controlada hasta que los codos toquen el suelo. Repite.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000097','dumbbell-front-raise','Elevación Frontal con Mancuernas','Un ejercicio de aislamiento que trabaja el deltoides anterior mediante una elevación hacia adelante.','Ponte de pie con las mancuernas a los costados, palmas frente a los muslos. Sube una o ambas mancuernas hacia adelante hasta la altura de los hombros. Baja de forma controlada. Repite.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000098','dumbbell-front-squat','Sentadilla Frontal con Mancuernas','Una sentadilla sosteniendo mancuernas apoyadas en los hombros, manteniendo el torso erguido y enfatizando los cuádriceps.','Sujeta una mancuerna en cada mano apoyadas sobre los hombros. Mantén los codos en alto y el torso erguido. Baja las caderas flexionando las rodillas hasta que los muslos queden paralelos al suelo. Empuja a través de los talones para ponerte de pie. Mantén la columna en posición neutra durante todo el movimiento. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000099','dumbbell-pistol-squat','Sentadilla Pistola con Mancuerna','La Sentadilla Pistola con Mancuerna es una variación avanzada de sentadilla a una pierna que desarrolla fuerza significativa en la parte inferior del cuerpo, equilibrio y movilidad, apuntando principalmente a los cuádriceps y glúteos.','Ponte de pie, sosteniendo una mancuerna en cada mano con los brazos colgando a los lados. Levanta una pierna recta hacia adelante, manteniéndola extendida durante todo el movimiento. Baja tu cuerpo doblando la rodilla de tu pierna de apoyo, manteniendo el pecho erguido y la espalda recta. Desciende hasta que tus glúteos estén cerca de tu talón o tu muslo esté paralelo al suelo, manteniendo el equilibrio. Empuja a través de tu talón para volver a la posición inicial, extendiendo completamente tu pierna de apoyo. Completa todas las repeticiones de un lado, luego cambia de pierna y repite para el otro lado por serie.','strength','compound','advanced',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000100','dumbbell-push-press','Press de Empuje con Mancuernas','Un press de hombros compuesto que usa el impulso de las piernas para desarrollar potencia en hombros y tríceps.','Párate sosteniendo mancuernas a la altura de los hombros, palmas hacia adelante. Dobla ligeramente las rodillas en una cuarta sentadilla. Empuja con las piernas para generar impulso y presiona las mancuernas hacia arriba. Extiende los brazos completamente arriba. Baja las mancuernas con control a la altura de los hombros.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000101','dumbbell-reverse-fly','Pájaro Invertido con Mancuernas','Un ejercicio de aislamiento inclinado que levanta las mancuernas hacia los lados, trabajando los deltoides posteriores y la espalda alta.','Inclínate hacia adelante desde las caderas sujetando mancuernas con los brazos colgando. Mantén la espalda recta y las rodillas ligeramente dobladas. Sube las mancuernas hacia los lados hasta la altura de los hombros. Aprieta los omóplatos en la parte superior. Baja las mancuernas de forma controlada. Repite el número de repeticiones deseado.','strength','isolation','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000102','dumbbell-romanian-deadlift','Peso Muerto Rumano con Mancuernas','Un peso muerto rumano con mancuernas que enfatiza el estiramiento de los isquiotibiales mediante una bisagra de cadera.','Ponte de pie sujetando mancuernas frente a los muslos con una ligera flexión de rodillas. Inclínate desde las caderas y empuja los glúteos hacia atrás. Baja las mancuernas a lo largo de las piernas hasta sentir el estiramiento en los isquiotibiales. Mantén la espalda recta y los hombros hacia atrás. Empuja las caderas hacia adelante para volver a la posición de pie. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000103','dumbbell-shoulder-press','Press de Hombros con Mancuernas','Un press vertical con mancuernas, sentado o de pie, que desarrolla las porciones anterior y lateral del deltoides.','Siéntate o ponte de pie sujetando mancuernas a la altura de los hombros con las palmas mirando hacia adelante. Empuja ambas mancuernas por encima de la cabeza hasta que los brazos queden completamente extendidos. Mantén el core contraído y evita arquear la zona lumbar. Baja las mancuernas de forma controlada hasta la altura de los hombros. No dejes que las mancuernas se desplacen detrás de la cabeza. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000104','dumbbell-side-bend','Flexión Lateral con Mancuerna','Un ejercicio de aislamiento de oblicuos de pie con mancuerna para desarrollar la fuerza lateral del core.','Párate erguido sosteniendo una mancuerna a un lado. Coloca la otra mano en la cadera o detrás de la cabeza. Inclínate lateralmente hacia el lado de la mancuerna, bajándola por el muslo. Vuelve a la posición erguida, luego inclínate al lado opuesto con los oblicuos. Completa todas las repeticiones por lado.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000105','dumbbell-snatch','Snatch con Mancuerna','Un levantamiento explosivo a un brazo que impulsa la mancuerna desde el suelo hasta encima de la cabeza en un movimiento fluido.','Ponte de pie con los pies al ancho de los hombros y la mancuerna en el suelo entre tus pies. Inclínate y agarra la mancuerna con una mano. Extiende caderas, rodillas y tobillos de forma explosiva para tirar de la mancuerna hacia arriba. Empuja la mancuerna por encima de la cabeza en un movimiento fluido. Bloquea el brazo y estabiliza en la parte superior. Completa las repeticiones de un lado y luego cambia.','olympic','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000106','dumbbell-split-squat','Sentadilla en Postura Dividida con Mancuernas','Una sentadilla en posición de tijera sosteniendo mancuernas a los lados, que trabaja los cuádriceps y glúteos una pierna a la vez.','Ponte en postura dividida sujetando mancuernas a los costados. Mantén el torso erguido y el core contraído. Baja la rodilla trasera hacia el suelo doblando ambas rodillas. Para cuando el muslo delantero quede paralelo al suelo. Empuja a través del talón delantero para volver a la posición de pie. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000107','dumbbell-tricep-extension','Extensión de Tríceps con Mancuerna','Una extensión de tríceps en una mano por encima de la cabeza para un desarrollo equilibrado del brazo.','Ponte de pie sujetando una mancuerna en una mano por encima de la cabeza. Baja la mancuerna detrás de la cabeza doblando el codo. Extiende el brazo de vuelta a la posición inicial. Mantén el codo cerca de la cabeza. Repite en ambos lados.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000108','dumbbell-upright-row','Remo al Mentón con Mancuernas','Un movimiento de tirón compuesto con mancuernas que trabaja los deltoides laterales y el trapecio superior.','Párate sosteniendo dos mancuernas frente a los muslos, palmas hacia el cuerpo. Tira de las mancuernas recto hacia arriba a lo largo del cuerpo, liderando con los codos. Sube hasta la altura del mentón con los codos por encima de las muñecas. Pausa brevemente, luego baja con control. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000109','dumbbell-windmill','Molino con Mancuerna','Este ejercicio de cuerpo completo desarrolla estabilidad del core, fuerza de hombros y movilidad de cadera al rotar el torso con una mancuerna sobre la cabeza, trabajando principalmente los oblicuos y deltoides laterales.','Ponte de pie con los pies al ancho de los hombros, sosteniendo una mancuerna sobre la cabeza con un brazo extendido. Gira tus pies ligeramente alejándolos del lado de la mancuerna, manteniendo el brazo recto y la vista en el peso. Inclínate desde las caderas, empujándolas hacia el lado de la mancuerna, y baja lentamente el torso hacia el suelo. Mantén la espalda recta y el brazo de la mancuerna vertical mientras alcanzas con tu mano libre el pie o el suelo. Invierte el movimiento impulsándote con las caderas y los oblicuos para regresar a la posición inicial. Completa todas las repeticiones por lado, luego cambia y repite para el otro lado.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000110','eagle-pose','Postura del Águila','Un equilibrio de pie con una pierna enroscada sobre la otra y los brazos entrelazados frente al pecho, sosteniendo una forma estrecha y compacta sobre una pierna flexionada.','Ponte de pie, flexiona ligeramente ambas rodillas y pasa el peso a un pie. Cruza el otro muslo sobre el muslo de apoyo y engancha el pie por detrás de la pantorrilla si llega. Cruza el brazo contrario por debajo, enrosca los antebrazos y acerca las palmas. Baja un poco sobre la pierna de apoyo y mantén durante el tiempo indicado, con los codos elevados. Desenrosca y repite del otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000111','easy-pose','Postura Fácil','Un sencillo sentado con las piernas cruzadas para respirar y meditar: la pelvis se mantiene erguida, la columna larga y las caderas se asientan sin tensión.','Siéntate en el suelo y cruza las espinillas con comodidad, cada pie bajo la rodilla contraria. Elévate sobre una manta doblada o un cojín hasta que las rodillas queden por debajo de las caderas. Alinea las costillas sobre la pelvis y deja las manos sobre los muslos. Mantén el sentado durante el tiempo indicado, respirando lenta y regularmente. Cambia qué espinilla queda delante en la siguiente ronda para repartir el tiempo entre ambos lados.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000112','extended-side-angle','Ángulo Lateral Extendido','Una postura de pie con base amplia, la rodilla delantera flexionada y el torso extendido sobre ese muslo, formando una línea larga desde el talón trasero hasta la mano de arriba.','Sepárate en una base amplia con el pie delantero girado hacia fuera y el trasero algo hacia dentro. Flexiona la rodilla delantera hasta que quede sobre el tobillo y mantén la pierna trasera estirada. Apoya el antebrazo delantero sobre el muslo, o la mano en el suelo o un bloque, y estira el brazo de arriba por encima de la oreja. Mantén la posición durante el tiempo indicado, girando el pecho hacia el techo. Estira la pierna delantera para subir y repite del otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000113','fire-hydrant','Hidrante de Fuego','Un ejercicio de glúteos con el peso corporal que se hace a cuatro apoyos: se levanta una rodilla hacia el lado, como un perro frente a un hidrante, mientras la cadera y la columna permanecen cuadradas respecto al suelo. Trabaja el glúteo medio y el resto de los abductores de cadera sin necesidad de equipo.','Colócate a cuatro apoyos con las manos bajo los hombros, las rodillas bajo la cadera y la espalda plana. Aprieta el tronco para que la cadera se mantenga nivelada y cuadrada respecto al suelo. Manteniendo la rodilla doblada a unos 90 grados, levanta una rodilla hacia el lado hasta que el muslo quede aproximadamente paralelo al suelo. Haz una breve pausa arriba sin rotar la pelvis ni inclinarte hacia el lado contrario al que trabaja. Baja la rodilla de vuelta a la posición inicial de forma controlada. Completa las repeticiones de un lado y luego cambia de pierna.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000114','fish-pose','Postura del Pez','Una extensión boca arriba apoyada en los antebrazos, con el pecho elevado y la cabeza inclinada atrás, que abre la parte frontal del pecho y la garganta.','Túmbate boca arriba con las piernas estiradas y los brazos junto al cuerpo, las palmas bajo las caderas. Presiona los antebrazos contra el suelo y eleva el pecho hacia el techo. Deja que la coronilla apoye ligeramente en el suelo sin cargar peso en el cuello. Mantén la posición durante el tiempo indicado, respirando hacia la parte alta del pecho. Levanta la cabeza y baja la espalda al suelo.','stretching','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000115','floor-kettlebell-pullover','Pullover con Pesa Rusa en Suelo','Un pullover realizado tumbado en el suelo con una pesa rusa sujetada por el asa o por las asas laterales. El suelo limita el rango de movimiento en comparación con la versión en banco, lo que reduce la tensión en los hombros y lo convierte en una buena opción para entrenar en casa o como ejercicio de prehabilitación.','Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies planos. Sujeta una pesa rusa por el asa con ambas manos sobre el pecho, brazos casi extendidos (ligera flexión de codos). Manteniendo el ángulo de los codos fijo, baja la pesa hacia atrás en arco hasta que los brazos toquen el suelo. Tira de la pesa de vuelta sobre el pecho siguiendo el mismo arco. Repite el número de repeticiones recomendado.','strength','compound','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000116','flutter-kicks','Flutter Kicks','Un ejercicio de core tumbado boca arriba alternando pequeñas patadas arriba y abajo mientras la zona lumbar permanece pegada al suelo.','Túmbate boca arriba con las piernas extendidas. Coloca las manos bajo los glúteos como apoyo. Levanta ambas piernas unos centímetros del suelo. Alterna las piernas arriba y abajo en un rango pequeño. Mantén el core contraído y la zona lumbar presionada contra el suelo. Continúa durante el tiempo o las repeticiones deseadas.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000117','garland-pose','Postura de la Guirnalda','Una sentadilla profunda sostenida con los talones apoyados y los codos empujando las rodillas hacia fuera, usada para abrir caderas, tobillos y zona lumbar.','Ponte de pie con los pies algo más separados que las caderas y las puntas ligeramente hacia fuera. Baja en cuclillas todo lo que permitan los tobillos, manteniendo los talones en el suelo. Junta las palmas frente al pecho y presiona los codos contra la cara interna de las rodillas. Mantén la posición durante el tiempo indicado, con el pecho alto y la columna larga. Empuja con los pies para volver a ponerte de pie.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000118','glute-bridge','Puente de Glúteos','Un ejercicio de activación de glúteos con el peso corporal realizado tumbado en el suelo.','Túmbate boca arriba con las rodillas flexionadas y los pies planos en el suelo. Eleva las caderas apretando los glúteos. Mantén brevemente en la parte alta con las caderas totalmente extendidas. Baja las caderas de forma controlada. Repite.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000119','glute-bridge-hold','Puente de Glúteos Isométrico','La parte alta del puente de glúteos mantenida en el tiempo: la cadera queda completamente extendida con hombros, caderas y rodillas en línea, de modo que los glúteos permanecen bajo tensión en lugar de encadenar repeticiones.','Túmbate boca arriba con las rodillas flexionadas y los pies apoyados, separados a la anchura de las caderas y lo bastante cerca como para rozar los talones con los dedos. Empuja con los talones y eleva la cadera hasta que el cuerpo forme una línea recta desde las rodillas hasta los hombros. Aprieta los glúteos y lleva las costillas hacia abajo para que la zona lumbar no tome el mando. Mantén la posición alta durante el tiempo indicado, con el peso en los talones. Baja la cadera de forma controlada para terminar la serie.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000120','glute-kickback','Patada de Glúteo','Un ejercicio de aislamiento de glúteos con peso corporal en posición de cuatro puntos para desarrollar el glúteo mayor.','Comienza a cuatro patas con las manos bajo los hombros y las rodillas bajo las caderas. Manteniendo la rodilla doblada a 90 grados, empuja el talón hacia el techo. Aprieta el glúteo en la parte superior del movimiento. Baja la pierna a la posición inicial con control. Completa todas las repeticiones y cambia de lado.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000121','glute-kickback-hold','Patada de Glúteo Isométrica','La posición final de la patada de glúteo mantenida en el tiempo: a cuatro apoyos con una pierna extendida hacia atrás a la altura de la cadera, la pelvis nivelada y el glúteo sosteniendo la pierna en el sitio.','Colócate a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas. Aprieta el tronco y mantén la pelvis nivelada; no dejes que el lado que trabaja rote hacia arriba. Extiende una pierna hacia atrás y arriba hasta que el muslo quede en línea con el torso. Mantén esa posición durante el tiempo indicado, con el cuello largo y la zona lumbar plana. Baja la pierna de forma controlada y repite del otro lado.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000122','goblet-squat','Sentadilla Goblet','Una sentadilla apta para principiantes con una pesa rusa sujetada a la altura del pecho que mejora la postura y la profundidad.','Sujeta una pesa rusa a la altura del pecho con ambas manos. Baja en sentadilla manteniendo el peso cerca del pecho. Vuelve a subir. Repite.','strength','compound','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000123','half-kneeling-hip-flexor-rock','Balanceo de Flexor de Cadera en Media Rodilla','La versión dinámica del estiramiento de flexor de cadera de rodillas: desde media rodilla las caderas se balancean hacia el estiramiento y vuelven, repetido en lugar de mantenido.','Apóyate sobre una rodilla con el otro pie plano en el suelo por delante. Mete ligeramente el coxis y aprieta el tronco para que la zona lumbar quede neutra. Balancea las caderas hacia delante hasta notar el alargamiento en la parte frontal del muslo trasero. Vuelve de forma controlada y repite con ritmo. Cambia de lado y repite el mismo número de veces.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000124','half-moon-pose','Postura de la Media Luna','Un equilibrio lateral de pie sobre una pierna y una mano, con la pierna de arriba elevada a la altura de la cadera y el pecho abierto hacia el techo.','Desde una base amplia, flexiona la rodilla delantera y apoya la mano de abajo en el suelo o un bloque por delante de ese pie. Desplaza el peso hacia delante y eleva la pierna trasera hasta dejarla paralela al suelo. Estira la pierna de apoyo y apila la cadera de arriba sobre la de abajo, con el brazo superior hacia el techo. Mantén el equilibrio durante el tiempo indicado, con el pie elevado en flexión. Baja el pie trasero y repite del otro lado.','strength','compound','advanced',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000125','hammer-curl','Curl de Martillo con Mancuernas','Una variación del curl de bíceps con agarre neutro que trabaja el braquiorradial.','De pie, sujeta las mancuernas a los lados con las palmas enfrentadas. Sube las mancuernas manteniendo las palmas hacia adentro. Aprieta en la parte alta y baja de forma controlada. Repite.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000126','handstand-hold','Pino Isométrico','Un mantenimiento estático libre, en equilibrio boca abajo sobre las manos con el cuerpo alineado en línea recta. Desarrolla fuerza de hombros, estabilidad de muñecas y tronco, y equilibrio.','Coloca las manos en el suelo a la anchura de los hombros aproximadamente y lanza las piernas hasta quedar invertido, una pierna tras otra. Empuja alto a través de los hombros y mantén los brazos bloqueados. Aprieta los glúteos y el abdomen para que el cuerpo forme una sola línea recta de las manos a los pies. Mantén la mirada entre las manos y sostén la posición haciendo pequeñas correcciones con los dedos. Baja de forma controlada, una pierna cada vez, o sal de la posición dando un paso.','strength','compound','advanced',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000127','handstand-push-ups','Flexiones en Pino','Un empuje invertido contra la pared, bajando la cabeza hacia el suelo y empujando de vuelta hasta el pino completo.','Sube a un pino contra la pared con las manos a la anchura de los hombros. Contrae el core y mantén el cuerpo recto. Baja la cabeza hacia el suelo flexionando los codos. Detente justo antes de que la cabeza toque el suelo. Empuja con las manos para volver al pino completo. Repite el número de repeticiones deseado.','strength','compound','advanced',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000128','happy-baby','Postura del Bebé Feliz','Una apertura de cadera boca arriba en la que las rodillas se acercan a las axilas y los pies se sujetan por fuera, liberando la cara interna de los muslos y la zona lumbar.','Túmbate boca arriba y acerca ambas rodillas al pecho. Agarra los bordes externos de los pies, o las espinillas si los pies quedan lejos. Abre las rodillas más allá de las costillas y coloca los tobillos sobre las rodillas, con las plantas hacia arriba. Empuja suavemente los pies contra las manos y mantén durante el tiempo indicado, con la zona lumbar en el suelo. Suelta los pies y baja las piernas.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000129','head-to-knee-pose','Postura de Cabeza a la Rodilla','Una flexión sentada sobre una pierna: una queda estirada y el otro pie se apoya en la cara interna del muslo, de modo que el isquiotibial se alarga de lado en lado.','Siéntate con una pierna estirada al frente y la otra rodilla abierta al lado, con ese pie en la cara interna del muslo. Gira el pecho hacia la pierna estirada para que el ombligo quede alineado con el muslo. Bascula desde las caderas y alcanza hacia delante a lo largo de la pierna con la columna larga. Mantén la flexión durante el tiempo indicado, respirando hacia la parte posterior de la pierna. Sube con la espalda plana y repite del otro lado.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000130','heel-flicks','Talones a los Glúteos','Un ejercicio de calentamiento de carrera que alterna los talones hacia los glúteos para aumentar la cadencia, flexionar dinámicamente las rodillas y preparar los isquiotibiales.','Ponte erguido con los pies bajo las caderas y los brazos flexionados como al correr. Empieza a trotar suavemente en el sitio. Lleva un talón rápidamente hacia el glúteo del mismo lado sin impulsar la rodilla hacia delante. Cambia de pie con rapidez y sigue alternando a un ritmo uniforme. Mantente ligero sobre los antepiés y conserva el torso erguido durante todo el intervalo.','cardio','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000131','heel-to-toe-walk','Marcha en Tándem','Un ejercicio de equilibrio y coordinación caminando sobre una línea imaginaria, colocando el talón de cada paso justo contra los dedos del otro pie para que la base de apoyo se reduzca casi a nada.','Elige una línea recta en el suelo, colócate sobre ella y extiende los brazos a los lados a la altura de los hombros. Da un paso al frente y coloca el talón justo delante de los dedos del pie de apoyo, en contacto con ellos. Pasa el peso al pie delantero de forma controlada y haz una pausa breve antes del siguiente paso. Lleva el pie de atrás hacia delante y colócalo de nuevo talón contra dedos, sin salirte de la línea. Fija la vista en un punto al frente en lugar de mirarte los pies, y corrige los desequilibrios con los brazos. Camina el número de pasos deseado, luego date la vuelta y regresa.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000132','heel-touches','Toques de Talón','Un ejercicio de core tumbado en el que haces un crunch ligero hacia un lado y llevas la mano hacia el talón, y luego alternas lados. Trabaja los oblicuos y la parte alta del abdomen con la zona lumbar pegada al suelo.','Túmbate boca arriba con las rodillas flexionadas y los pies apoyados en el suelo, a la anchura de las caderas aproximadamente. Levanta ligeramente la cabeza y los hombros del suelo y estira los brazos a lo largo de los costados. Haz un crunch hacia un lado y lleva esa mano hacia el talón del mismo lado. Vuelve al centro y alcanza el talón contrario. Sigue alternando lados con un ritmo fluido mientras la zona lumbar permanece en el suelo. Continúa el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000133','hero-pose','Postura del Héroe','Un sentado de rodillas en el que las caderas descienden entre los talones, alargando el cuádriceps y la parte frontal de los tobillos mientras la columna se mantiene erguida.','Arrodíllate con las rodillas juntas y los pies algo más separados que las caderas, con el empeine apoyado. Baja las caderas entre los talones, usando un bloque o cojín si el suelo queda lejos. Alinea las costillas sobre la pelvis y apoya las manos en los muslos. Mantén el sentado durante el tiempo indicado, con el peso repartido entre ambos isquiones. Sal apoyándote en las manos y estirando una pierna cada vez.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000134','high-knees','Rodillas Altas','Un ejercicio cardio con peso corporal en el que las rodillas suben a la altura de la cadera en alternancia rápida.','Mantente erguido con los pies a la anchura de las caderas. Lleva una rodilla arriba hacia el pecho bombeando el brazo opuesto. Cambia de pierna rápidamente, espejando la acción del brazo. Continúa alternando a ritmo rápido. Continúa durante el intervalo de trabajo indicado.','cardio','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000135','high-plank','Plancha Alta','Una variación de plancha con los brazos totalmente extendidos en posición de push-up.','Empieza en posición de push-up con los brazos totalmente extendidos. Mantén el cuerpo en línea recta de cabeza a talones. Contrae el core y mantén la posición. Respira de forma regular durante el ejercicio.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000136','hollow-body-hold','Mantenimiento del Cuerpo Hueco','Un mantenimiento isométrico de core de la gimnasia, que entrena la tensión de cuerpo completo con la columna en ligera forma de C.','Acuéstate boca arriba con los brazos extendidos sobre la cabeza y las piernas rectas. Presiona la zona lumbar firmemente contra el suelo. Levanta ligeramente los hombros, la cabeza y las piernas del suelo. Mantén la posición con brazos y piernas extendidos, cuerpo en forma de plátano poco profundo. Sostén durante el tiempo indicado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000137','inchworm','Inchworm','Un ejercicio de calentamiento y movilidad con el peso corporal: desde una flexión hacia delante de pie, caminas con las manos por el suelo hasta que el cuerpo queda en plancha baja, con los codos flexionados como en el punto más bajo de una flexión de brazos, y luego las caminas de vuelta hacia los pies. Estira los isquiotibiales y las pantorrillas mientras los hombros, el pecho y el tronco sostienen la plancha baja.','Ponte de pie, erguido, con los pies separados aproximadamente al ancho de las caderas. Flexiónate hacia delante desde las caderas y apoya las manos en el suelo delante de los pies, flexionando un poco las rodillas si lo necesitas. Camina con las manos hacia delante, una tras otra, manteniendo las piernas lo más estiradas que puedas con comodidad, hasta que el cuerpo quede en línea recta cerca del suelo. Flexiona los codos para que el pecho quede justo por encima del suelo, como en el punto más bajo de una flexión de brazos, y haz una breve pausa con el tronco firme. Camina con las manos de vuelta hacia los pies con pasos cortos, elevando las caderas, hasta volver a la flexión hacia delante. Levántate o pasa directamente a la siguiente repetición.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000138','isometric-neck-side','Flexión Lateral Isométrica de Cuello','Un ejercicio estático de cuello que usa la mano como resistencia contra la cabeza, trabajando el esternocleidomastoideo y los escalenos sin equipo.','Siéntate o ponte de pie erguido. Coloca la palma de una mano en el lado de la cabeza, por encima de la oreja. Empuja la cabeza contra la mano resistiendo por igual con la mano: la cabeza no se mueve. Mantén la contracción isométrica de 5 a 10 segundos. Suelta lentamente y repite en el mismo lado durante la serie. Cambia de lado y repite.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000139','jackknife-sit-up','Abdominal navaja','Un crunch de cuerpo completo realizado desde el suelo, levantando las piernas y el torso simultáneamente para tocar las manos con los pies.','Acuéstate boca arriba en el suelo con los brazos extendidos por encima de la cabeza y las piernas estiradas. Levanta simultáneamente el torso y las piernas rectas del suelo. Lleva las manos hacia los pies mientras estos suben — encuéntralos sobre las caderas. Baja el torso y las piernas de vuelta al suelo con control. Repite el número recomendado de repeticiones.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000140','jump-squat','Sentadilla con Salto','Una sentadilla pliométrica con peso corporal donde explotas hacia arriba en un salto vertical.','Mantente con los pies a la anchura de los hombros. Baja a una media sentadilla con los brazos atrás. Explota hacia arriba, balanceando los brazos y saltando lo más alto posible. Aterriza suave en media sentadilla para absorber el impacto. Repite sin pausa el número de repeticiones indicado.','plyometrics','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000141','jumping-jacks','Saltos de Tijera','Este clásico ejercicio dinámico de cuerpo completo eleva la frecuencia cardíaca y trabaja pantorrillas, hombros, cuádriceps y glúteos, siendo excelente para calentar o acondicionar.','Ponte de pie con los pies juntos y los brazos a los lados. Simultáneamente, salta abriendo las piernas y levantando los brazos por encima de la cabeza. Asegúrate de que tus brazos se junten o casi se junten por encima de tu cabeza. Salta juntando los pies de nuevo mientras bajas los brazos a los lados. Mantén un movimiento continuo y rítmico.','cardio','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000142','kettlebell-close-grip-floor-press','Press de Suelo con Agarre Cerrado con Pesa Rusa','Un press de suelo con una sola pesa rusa agarrada con ambas manos juntas, que desplaza el énfasis del pecho a los tríceps.','Túmbate boca arriba en el suelo con las rodillas flexionadas y los pies apoyados. Sujeta una única pesa rusa por el asa con ambas manos juntas, con la pesa apoyada en el pecho y los codos bien pegados a las costillas. Activa el core y empuja la pesa rusa recto hacia arriba hasta estirar del todo los brazos. Baja de forma controlada hasta que la parte alta de los brazos toque el suelo y haz una breve pausa. Vuelve a empujar hacia arriba hasta la extensión completa. Repite el número de repeticiones recomendado.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000143','kettlebell-deadlift','Peso muerto con pesa rusa','Un peso muerto con pesa rusa que fortalece glúteos, isquiotibiales y zona lumbar con un patrón de bisagra de cadera.','Párate con los pies a la anchura de los hombros y la pesa rusa entre los pies. Bisagra en las caderas y flexiona las rodillas para agarrar el asa. Contrae el core y mantén la espalda plana. Empuja a través de los talones para ponerte de pie con la pesa rusa. Bloquea en la parte superior con los hombros hacia atrás. Baja la pesa rusa de vuelta al suelo con control.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000144','kettlebell-goblet-lunge','Zancada Goblet con Kettlebell','Este ejercicio compuesto unilateral fortalece los cuádriceps, glúteos e isquiotibiales al realizar una zancada con una kettlebell en posición de copa, mejorando la fuerza y estabilidad del tren inferior.','Ponte de pie sosteniendo una kettlebell por sus cuernos a la altura del pecho, con los codos pegados al cuerpo, en la posición de copa. Da un paso controlado hacia adelante con una pierna, bajando las caderas hasta que ambas rodillas estén flexionadas aproximadamente a 90 grados. Asegúrate de que tu rodilla delantera esté alineada sobre tu tobillo y tu rodilla trasera flote justo por encima del suelo. Impúlsate a través del talón de tu pie delantero para volver a la posición inicial, manteniendo el equilibrio y la tensión del core. Completa todas las repeticiones por lado antes de cambiar, o alterna las piernas por serie.','strength','compound','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000145','kettlebell-halo','Halo con pesa rusa','Un ejercicio de movilidad de hombros donde se hace girar una pesa rusa alrededor de la cabeza. Calienta el manguito rotador, la columna torácica y la cintura escapular con carga mínima.','Párate erguido con el core contraído, sosteniendo una pesa rusa ligera por las asas (boca abajo) a la altura del pecho. Sube la campana a un lado de la cabeza y hazla pasar por detrás en un círculo suave. Tráela de vuelta a la posición inicial frente a tu cara. Invierte la dirección cada pocas repeticiones. Repite el número recomendado de repeticiones o tiempo.','strength','isolation','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000146','kettlebell-hammer-curl','Curl martillo con pesa rusa','Un curl con agarre neutro sosteniendo el asa de una pesa rusa de modo que la campana cuelgue junto a la muñeca. La masa descentrada y el agarre neutro trabajan principalmente el braquial y el braquiorradial.','Párate sosteniendo una pesa rusa en una mano, agarrando el asa en posición neutra (palma hacia el cuerpo). La campana descansa sobre o junto al antebrazo. Mantén el codo pegado al costado y sube la campana hacia el hombro. Aprieta en la parte superior y baja con control. Completa todas las repeticiones en un lado y luego cambia.','strength','isolation','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000147','kettlebell-kickstand-deadlift','Peso Muerto Kickstand con Kettlebell','Un movimiento de bisagra de cadera en postura escalonada con una kettlebell que carga la pierna delantera mientras el pie trasero estabiliza.','Coloca un pie detrás de modo que solo los dedos toquen el suelo. Sostén una kettlebell en la mano del lado del pie trasero. Bisagra en la cadera bajando la kettlebell hacia la espinilla con la espalda recta. Mantén la mayor parte del peso en el pie delantero. Empuja con el talón delantero para volver a la posición inicial. Cambia de lado.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000148','kettlebell-lunge-press','Zancada con press de pesa rusa','Un ejercicio de cuerpo completo que combina una zancada con un press de pesa rusa a un brazo.','Sostén una pesa rusa a la altura del hombro con un brazo. Da un paso adelante en zancada con la pierna contraria. Mientras haces la zancada, empuja la pesa rusa por encima de la cabeza. Bloquea el brazo en la parte superior del press. Da un paso atrás de vuelta a la posición de pie mientras bajas la pesa rusa. Completa las repeticiones en un lado y luego cambia.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000149','kettlebell-offset-reverse-lunge-and-press','Zancada inversa con press desequilibrado de pesa rusa','Una zancada inversa combinada con un press de pesa rusa a un brazo, con carga descompensada que exige estabilidad del core.','Sostén una pesa rusa a la altura del hombro en un lado. Da un paso hacia atrás en zancada inversa con la pierna contraria. Al llegar a la parte inferior de la zancada, empuja la pesa rusa por encima de la cabeza. Empuja con el talón delantero para volver a ponerte de pie. Baja la pesa rusa de vuelta a la altura del hombro. Completa las repeticiones en un lado y luego cambia.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000150','kettlebell-overhead-carry','Paseo con Kettlebell sobre la Cabeza','Un paseo cargado con una sola kettlebell bloqueada por encima de la cabeza, donde la bola cuelga por detrás de la muñeca y tira del brazo hacia atrás, lo que la hace más difícil de sostener quieta que una mancuerna.','Lleva una kettlebell en cargada y press hasta el bloqueo, dejando que la bola se asiente sobre el dorso del antebrazo. Estira el codo del todo y gira el brazo para que la bola quede por detrás y por encima de la muñeca, no desplazada a un lado. Mantén el hombro activo: empuja el peso hacia el techo y deja que la escápula rote hacia arriba con él en lugar de forzarla hacia abajo. Aprieta el tronco y camina hacia delante con zancadas regulares, con la bola alineada sobre hombro y cadera. Mantén la muñeca recta; dejar que se doble hacia atrás es lo que hace que una kettlebell arriba se sienta inestable. Carga la distancia deseada, baja de forma controlada y repite por el otro lado.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000151','kettlebell-overhead-tricep-extension','Extensión de tríceps por encima de la cabeza con pesa rusa','Una extensión de tríceps por encima de la cabeza sosteniendo una pesa rusa por las asas con ambas manos. La carga descentrada jala la campana detrás de la cabeza para un estiramiento profundo de la cabeza larga.','Párate o siéntate sosteniendo una pesa rusa por las asas (boca abajo) con ambas manos por encima de la cabeza. Brazos completamente extendidos, campana sobre la cabeza. Flexiona solo los codos para bajar la campana detrás de la cabeza en un arco controlado. Mantén los brazos verticales y pegados a la cabeza; solo los antebrazos se mueven. Extiende los codos para devolver la campana por encima de la cabeza. Repite el número recomendado de repeticiones.','strength','isolation','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000152','kettlebell-pistol-squat','Sentadilla pistola con pesa rusa','Una sentadilla a una pierna con la pesa rusa al pecho que exige fuerza y equilibrio avanzados.','Sostén una pesa rusa a la altura del pecho con ambas manos. Párate en una pierna con la otra extendida hacia adelante. Baja las caderas en una sentadilla a una sola pierna. Mantén la pierna elevada fuera del suelo durante todo el movimiento. Empuja a través del talón de apoyo para volver a ponerte de pie. Completa las repeticiones en un lado y luego cambia.','strength','compound','advanced',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000153','kettlebell-reverse-lunge','Zancada Inversa con Kettlebell','Este ejercicio compuesto unilateral desarrolla fuerza y estabilidad en la parte inferior del cuerpo, trabajando principalmente glúteos y cuádriceps, e involucrando isquiotibiales, glúteo medio y oblicuos.','Ponte de pie con una kettlebell en una mano, el brazo extendido hacia abajo, en el mismo lado de la pierna que retrocederá. Da un paso hacia atrás con una pierna, bajando las caderas hasta que ambas rodillas estén flexionadas aproximadamente a 90 grados. Mantén la espinilla delantera vertical y el pecho erguido, asegurándote de que la rodilla trasera flote justo por encima del suelo. Impúlsate a través del talón delantero para volver a la posición inicial. Completa todas las repeticiones por lado antes de cambiar al otro lado.','strength','compound','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000154','kettlebell-rotational-lunge','Zancada rotacional con pesa rusa','Una zancada lateral con pesa rusa y rotación del torso que trabaja piernas, glúteos y oblicuos en varios planos.','Sostén una pesa rusa con ambas manos a la altura del pecho. Da un paso hacia un lado en una zancada lateral. Rota el torso hacia la pierna que hace la zancada. Lleva la pesa rusa hacia la rodilla flexionada. Empuja con la pierna de la zancada para volver al centro. Completa las repeticiones en un lado y luego cambia.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000155','kettlebell-russian-twist','Giro ruso con pesa rusa','Un Russian Twist con pesa rusa realizado sentado con los pies en el aire, que entrena los oblicuos mediante rotaciones del torso.','Siéntate en el suelo con las rodillas flexionadas y los pies levantados del suelo. Sostén una pesa rusa con ambas manos frente al pecho. Inclínate ligeramente hacia atrás para activar el core. Rota el torso hacia un lado llevando la pesa rusa junto a la cadera. Rota hacia el lado opuesto en un movimiento controlado. Repite el número deseado de repeticiones.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000156','kettlebell-single-leg-deadlift','Peso muerto a una pierna con pesa rusa','Un peso muerto a una pierna con pesa rusa que fortalece glúteos e isquiotibiales y pone a prueba el equilibrio.','Sostén una pesa rusa en una mano y párate en la pierna contraria. Bisagra en la cadera y baja la pesa rusa hacia el suelo. Extiende la pierna libre hacia atrás para mantener el equilibrio. Baja hasta que el torso quede paralelo al suelo. Empuja a través del talón de apoyo para volver a ponerte de pie. Completa las repeticiones en un lado y luego cambia.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000157','kettlebell-squat','Sentadilla con Kettlebell','Una variante de sentadilla sosteniendo una kettlebell con ambas manos colgando baja entre las piernas, añadiendo carga a un patrón de sentadilla estándar.','Ponte de pie con los pies separados al ancho de los hombros, sosteniendo una kettlebell con ambas manos frente a ti. Deja que la kettlebell cuelgue naturalmente entre tus piernas mientras contraes el core. Flexiona las caderas y las rodillas para bajar en sentadilla, manteniendo la kettlebell cerca del cuerpo. Empuja con los pies para volver a la posición inicial. Repite el número deseado de repeticiones.','strength','compound','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000158','kettlebell-sumo-deadlift','Peso muerto sumo con pesa rusa','Un peso muerto con postura amplia usando una sola pesa rusa entre los pies. La postura amplia y la carga cerca del cuerpo hacen de este un patrón dominante de cuádriceps y glúteos que es fácil de aprender.','Párate con una postura amplia y los pies ligeramente girados hacia afuera, con una pesa rusa en el suelo entre los pies. Baja con la espalda plana, las rodillas alineadas con los pies, y agarra el asa con ambas manos. Empuja el suelo y extiende caderas y rodillas juntas para ponerte de pie. Aprieta los glúteos en la parte superior. Baja la campana con control de vuelta al suelo empujando las caderas hacia atrás. Repite el número recomendado de repeticiones.','strength','compound','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000159','kettlebell-sumo-high-pull','Jalón sumo al mentón con pesa rusa','Un jalón con pesa rusa desde el suelo hasta la altura del mentón con postura amplia, combinando una bisagra con un remo en pie para desarrollar el trapecio superior de forma explosiva.','Párate con los pies más anchos que los hombros, los dedos ligeramente girados hacia afuera y una pesa rusa en el suelo entre los pies. Bisagra hacia abajo y agarra el asa con ambas manos. Empuja con los pies y extiende las caderas de forma explosiva para jalar la pesa rusa hacia arriba. Al subir, lleva los codos hacia arriba y afuera hasta que el asa alcance la altura del mentón. Baja la pesa rusa de vuelta entre las piernas con control. Repite el número recomendado de repeticiones.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000160','kettlebell-swing','Swing con pesa rusa','Un movimiento explosivo de bisagra de cadera con pesa rusa para potencia y acondicionamiento físico.','Párate con los pies a la anchura de los hombros y la pesa rusa en el suelo por delante. Bisagra en las caderas, agarra la pesa rusa y llévala hacia atrás entre las piernas. Extiende las caderas de forma explosiva para balancear la pesa rusa hasta la altura del pecho. Deja que la pesa rusa vuelva a balancearse entre las piernas. Repite en un movimiento fluido.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000161','kettlebell-swing-clean','Swing y cargada con pesa rusa','Un clean con pesa rusa iniciado desde el swing, que lleva el peso hasta la posición de rack en el hombro.','Párate con los pies a la anchura de los hombros y la pesa rusa entre los pies. Bisagra en las caderas y agarra el asa con una mano. Balancea la pesa rusa hacia atrás entre las piernas. Extiende las caderas hacia adelante para jalar la pesa rusa hasta el hombro. Recibe la pesa rusa en la posición de rack sobre el hombro. Completa las repeticiones en un lado y luego cambia.','olympic','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000162','kettlebell-turkish-get-ups','Levantamiento Turco con Kettlebell','Un ejercicio de cuerpo completo con kettlebell que pasa de estar tumbado a de pie mientras se mantiene el peso bloqueado por encima de la cabeza, trabajando la fuerza, la estabilidad y la movilidad de todo el cuerpo.','Túmbate boca arriba sosteniendo una kettlebell por encima de la cabeza con una mano. Flexiona la rodilla del mismo lado y apoya el pie plano. Rueda hasta apoyarte en el codo opuesto y luego en la mano. Empuja las caderas hacia arriba y lleva la pierna estirada hacia atrás a una zancada. Ponte de pie por completo manteniendo la kettlebell bloqueada por encima de la cabeza. Invierte la secuencia para volver a la posición inicial.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000163','kettlebell-windmills','Molino de Viento con Pesa Rusa','Un ejercicio de pesa rusa con el brazo bloqueado por encima de la cabeza, que combina estabilidad de hombro y bisagra lateral de cadera.','Párate sosteniendo una pesa rusa bloqueada sobre la cabeza con una mano. Gira los pies unos 45 grados alejándolos del brazo de trabajo. Con la pesa rusa arriba, inclínate lateralmente desde las caderas. Lleva la mano opuesta hacia el pie. Empuja las caderas hacia atrás para volver a la posición erguida. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000164','knee-push-ups','Push-Up en Rodillas','Una variante de flexión apta para principiantes, con las rodillas apoyadas en el suelo para reducir la carga sobre el tren superior.','Comienza en posición de push-up con las rodillas en el suelo. Coloca las manos a la anchura de los hombros en el suelo. Mantén el cuerpo en línea recta desde las rodillas hasta los hombros. Baja el pecho hacia el suelo doblando los codos. Empuja con las manos para volver a la posición inicial. Repite el número de repeticiones deseado.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000165','knee-to-chest-stretch','Estiramiento Rodilla al Pecho','Un estiramiento tumbado que libera los glúteos y la zona lumbar al abrazar una rodilla contra el pecho.','Acuéstate boca arriba con ambas piernas estiradas. Lleva una rodilla y abrázala al pecho con ambas manos. Mantén la otra pierna relajada en el suelo. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000166','kneeling-hip-flexor-stretch','Estiramiento de Flexores de Cadera Arrodillado','Un estiramiento en semiarrodillado que abre los flexores de cadera de la pierna trasera empujando la cadera adelante.','Arrodíllate sobre una rodilla con el otro pie plano al frente. Mantén el torso erguido y el core ligeramente activado. Empuja la cadera adelante hasta sentir el estiramiento en el frente de la cadera trasera. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000167','kneeling-wrist-stretch','Estiramiento de Muñecas Arrodillado','Un estiramiento de rodillas para los flexores del antebrazo y las muñecas, con las palmas abajo y los dedos hacia atrás.','Ponte en cuadrupedia y apoya las palmas planas en el suelo. Gira las manos para que los dedos apunten hacia las rodillas. Mantén las palmas abajo y desplaza el peso atrás suavemente. Mantén de 20 a 30 segundos, respirando de forma constante.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000168','lateral-raise','Elevación Lateral con Mancuernas','Un movimiento de aislamiento que trabaja el deltoides lateral para ganar anchura en los hombros.','Párate con mancuernas a los costados. Eleva las mancuernas hacia los lados hasta que los brazos queden paralelos al suelo. Baja de forma controlada. Repite.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000169','legs-up-the-wall','Piernas en la Pared','Una posición restaurativa con las caderas cerca de una pared y las piernas apoyadas en vertical, pensada para recuperar y no para esforzarse.','Siéntate de lado junto a una pared con una cadera en contacto con ella. Sube las piernas por la pared mientras te tumbas, de modo que las caderas queden cerca de la base. Deja las piernas apoyadas en la pared, los pies relajados y los brazos abiertos a los lados. Permanece durante el tiempo indicado, respirando despacio. Flexiona las rodillas y rueda hacia un lado para salir.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000170','lizard-stretch','Estiramiento del Lagarto','Un estiramiento en zancada profunda que abre los flexores de cadera, la ingle y los glúteos con los antebrazos hacia el suelo.','Da un paso adelante a una zancada profunda, con el pie bien abierto. Baja ambos antebrazos hacia el suelo por dentro del pie delantero. Extiende la pierna trasera y deja que la cadera baje. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000171','locust-pose','Postura del Saltamontes','Un sostén boca abajo en el que pecho, brazos y piernas se despegan del suelo, de modo que toda la cadena posterior trabaja de forma isométrica sin carga externa.','Túmbate boca abajo con los brazos junto al cuerpo y la frente en la esterilla. Alarga la nuca y estira las yemas de los dedos hacia los pies. Eleva a la vez el pecho, los brazos y ambas piernas. Mantén la posición elevada durante el tiempo indicado, con la mirada hacia el suelo. Baja todo a la vez y descansa.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000172','low-lunge','Zancada Baja','Un estiramiento en paso largo con la rodilla trasera apoyada: las caderas se hunden hacia delante y alargan el flexor de la cadera de la pierna de atrás.','Desde la posición de rodillas, adelanta un pie para que la rodilla quede sobre el tobillo. Apoya la rodilla trasera en el suelo y deja el empeine estirado. Mete ligeramente el coxis y empuja las caderas hacia delante hasta notar el alargamiento en la parte frontal del muslo trasero. Eleva el pecho, sube los brazos si te resulta agradable y mantén durante el tiempo indicado. Vuelve atrás y repite del otro lado.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000173','low-lunge-to-half-split','Zancada Baja a Medio Split','Una secuencia en movimiento para isquiotibiales y flexores de cadera: desde una zancada baja las caderas retroceden sobre la rodilla trasera y la pierna delantera se estira en medio split, y después las caderas vuelven a deslizarse hacia delante.','Empieza en zancada baja con la rodilla trasera en el suelo y la delantera sobre el tobillo. Apoya las manos en el suelo o en bloques a ambos lados del pie delantero. Lleva las caderas atrás sobre la rodilla trasera y estira la pierna delantera con el pie en flexión. Sostén el medio split un instante y desliza las caderas hacia delante otra vez a la zancada. Repite las veces indicadas y cambia de lado.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000174','lunge','Zancada','Una zancada hacia delante con el peso corporal, entrenando cuádriceps, glúteos y equilibrio una pierna a la vez.','Párate erguido con los pies a la anchura de las caderas. Da un paso adelante largo con una pierna. Baja la rodilla trasera hacia el suelo hasta que ambas rodillas formen ángulos de 90 grados. Empuja con el talón delantero para volver a la posición de pie. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000175','mountain-climbers','Mountain Climbers','Un ejercicio dinámico de peso corporal que combina trabajo de core con cardio.','Comienza en posición de plancha alta. Lleva una rodilla hacia el pecho. Cambia rápidamente de pierna llevando la otra rodilla hacia adelante. Continúa alternando a un ritmo brioso. Repite.','cardio','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000176','mountain-pose','Postura de la Montaña','La postura básica de pie: pies enraizados, piernas activas, columna larga y hombros relajados. Es la referencia de alineación con la que se miden las demás posturas de pie.','Ponte de pie con los pies a la anchura de las caderas y reparte el peso por igual entre ambos. Activa ligeramente los muslos y deja caer el coxis para que la pelvis quede neutra. Alinea las costillas sobre la pelvis y la cabeza sobre las costillas, con los brazos relajados a los lados. Mantén la postura durante el tiempo indicado, respirando con regularidad. Observa dónde queda el peso y devuélvelo al centro de cada pie.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000177','neck-side-stretch','Estiramiento Lateral de Cuello','Un estiramiento suave que alarga el trapecio superior y el lateral del cuello inclinando la oreja hacia el hombro.','Siéntate o párate erguido con los hombros relajados. Inclina la cabeza para que una oreja baje hacia ese hombro. Apoya esa mano sobre la cabeza para un peso suave. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000178','one-arm-dumbbell-push-press','Push Press con Mancuerna a Un Brazo','Un push press unilateral con una sola mancuerna. El impulso de piernas te permite lanzar cargas más pesadas por encima de la cabeza que un press estricto a un brazo, y la carga asimétrica exige una fuerte contención anti-flexión lateral.','De pie con la mancuerna en un hombro, palma hacia adentro (neutro). Pies a la anchura de los hombros, core contraído, brazo libre al costado para equilibrio. Flexiona ligeramente las rodillas manteniendo el torso vertical. Extiende las piernas de forma explosiva y empuja la mancuerna por encima de la cabeza en un solo movimiento. Bloquea el codo arriba y baja la mancuerna al hombro con control. Completa todas las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000179','one-arm-dumbbell-shoulder-press','Press de Hombros con Mancuerna a Un Brazo','Un press por encima de la cabeza de pie con una sola mancuerna. Trabajar un lado cada vez carga el hombro y el tríceps y obliga al tronco a resistir la inclinación hacia la mano vacía.','Colócate de pie con los pies a la anchura de las caderas y sujeta una mancuerna a la altura de un hombro con la palma hacia delante. Contrae el abdomen y deja el brazo libre relajado a un lado. Empuja la mancuerna en vertical por encima de la cabeza hasta extender del todo el brazo. Haz una breve pausa arriba con la parte superior del brazo junto a la oreja. Baja la mancuerna de nuevo al hombro de forma controlada. Completa las repeticiones con un brazo y luego cambia de lado.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000180','one-arm-dumbbell-swing','Swing con Mancuerna a un Brazo','Este ejercicio dinámico desarrolla potencia explosiva en glúteos e isquiotibiales mediante una potente bisagra de cadera, involucrando el core y los hombros para un entrenamiento de cuerpo completo.','Párate con los pies al ancho de los hombros, una mancuerna en el suelo ligeramente delante de ti. Haz una bisagra de cadera, manteniendo la espalda recta, y agarra la mancuerna con una mano. Lleva la mancuerna hacia atrás entre tus piernas, luego impulsa explosivamente tus caderas hacia adelante. Balancea la mancuerna hasta la altura del pecho, manteniendo tu brazo relajado y estirado. Permite que la mancuerna baje, haciendo una bisagra de cadera mientras desciende. Repite las repeticiones deseadas por lado, manteniendo el control.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000181','one-arm-kettlebell-bicep-curl','Curl de Bíceps con Pesa Rusa a Un Brazo','Un curl de bíceps unilateral con pesa rusa que entrena cada brazo por separado e implica con fuerza el antebrazo.','De pie, sostén una pesa rusa en una mano. Mantén el codo pegado al costado. Sube la pesa rusa hacia el hombro flexionando el bíceps. Aprieta en la parte superior del movimiento. Baja la pesa rusa con control. Completa las repeticiones de un lado y luego cambia.','strength','isolation','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000182','one-arm-kettlebell-bottoms-up-press','Press Strict con Pesa Rusa Invertida a Un Brazo','Un press estricto por encima de la cabeza con la pesa rusa boca abajo: la bola arriba y el asa en la palma. La carga invertida exige un agarre fuerte, estabilidad perfecta de hombro y una trayectoria impecable.','Limpia una pesa rusa ligera a la posición de rack y luego inclínala para que la bola apunte hacia arriba y el asa quede en la palma. Agarra el asa con fuerza; la muñeca absolutamente recta y vertical. Contrae el core y empuja la bola recto hacia arriba sin dejarla caer. Bloquea el codo arriba con la bola todavía perfectamente vertical. Baja lentamente a la posición de rack manteniendo la pesa vertical durante todo el descenso. Completa todas las repeticiones de un lado y luego cambia.','strength','compound','advanced',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000183','one-arm-kettlebell-floor-glute-bridge-press','Press en Puente de Glúteos en Suelo con Pesa Rusa a Un Brazo','Un ejercicio combinado en el suelo que une un puente de glúteos con un press de pesa rusa a un brazo.','Túmbate boca arriba con las rodillas dobladas y los pies planos en el suelo. Sostén una pesa rusa en una mano a la altura del hombro. Eleva las caderas en un puente de glúteos. Empuja la pesa rusa recto hacia el techo. Baja la pesa rusa y las caderas con control. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000184','one-arm-kettlebell-floor-press','Press en Suelo con Pesa Rusa a Un Brazo','Un press de pecho unilateral con pesa rusa ejecutado tumbado en el suelo, que acorta el recorrido y trabaja pectoral y tríceps.','Túmbate boca arriba en el suelo con las rodillas dobladas. Sostén una pesa rusa en un hombro con una mano. Empuja la pesa rusa recto hacia arriba hasta que el brazo quede completamente extendido. Baja la pesa rusa hasta que la parte superior del brazo toque el suelo. Mantén el core contraído durante todo el ejercicio. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000185','one-arm-kettlebell-front-squat','Sentadilla Frontal con Pesa Rusa a Un Brazo','Una sentadilla frontal con una pesa rusa apoyada en un solo hombro, que obliga al core a resistir la inclinación lateral.','Sostén una pesa rusa en posición de rack en un hombro. De pie con los pies a la anchura de los hombros. Baja en sentadilla flexionando las rodillas y las caderas. Mantén el pecho alto y el torso erguido durante todo el ejercicio. Impulsa a través de los talones para volver a ponerte de pie. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000186','one-arm-kettlebell-push-press','Push Press con Pesa Rusa a Un Brazo','Un press unilateral con pesa rusa que usa un impulso de piernas para llevar el peso por encima de la cabeza.','Sostén una pesa rusa en posición de rack en un hombro. De pie con los pies a la anchura de los hombros. Flexiona ligeramente las rodillas. Extiende las piernas de forma explosiva y empuja la pesa rusa por encima de la cabeza. Bloquea el codo en la parte superior. Baja la pesa rusa al hombro con control. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000187','one-arm-kettlebell-shoulder-press','Press de Hombro con Pesa Rusa a Un Brazo','Un press de hombro estricto a un brazo con pesa rusa, que exige estabilidad del core para evitar la inclinación lateral.','Sostén una pesa rusa en posición de rack en un hombro. De pie con los pies a la anchura de las caderas. Empuja la pesa rusa recto hacia arriba hasta bloquear el codo. Mantén el core apretado durante todo el ejercicio. Baja la pesa rusa a la posición de rack con control. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000188','one-arm-kettlebell-swing','Swing con Pesa Rusa a Un Brazo','Un swing de pesa rusa a un brazo, un movimiento balístico de bisagra de cadera que desarrolla potencia en glúteos e isquiotibiales.','De pie con los pies a la anchura de los hombros y la pesa rusa en el suelo frente a ti. Bisagra en las caderas y agarra la pesa rusa con una mano. Lleva la pesa rusa hacia atrás entre las piernas. Impulsa las caderas hacia adelante para lanzar la pesa rusa hasta la altura del pecho. Deja que la gravedad lleve la pesa rusa de vuelta entre las piernas. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000189','one-arm-kettlebell-tricep-kickback','Extensión de Tríceps a Un Brazo con Pesa Rusa','Una extensión de tríceps unilateral con pesa rusa: inclínate, fija el brazo al costado paralelo al suelo y extiende el codo hacia atrás.','Inclínate hacia delante flexionando las caderas con la espalda recta y las rodillas ligeramente flexionadas. Sujeta una pesa rusa por el asa con una mano, con la palma hacia el cuerpo. Fija la parte alta del brazo al costado de modo que quede paralela al suelo; el antebrazo cuelga recto hacia abajo. Extiende el codo hacia atrás para estirar el brazo del todo por detrás de ti, manteniendo inmóvil la parte alta del brazo. Aprieta el tríceps en la extensión completa y vuelve de forma controlada a la posición inicial. Completa todas las repeticiones de un lado y luego cambia de mano.','strength','isolation','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000190','one-arm-single-leg-dumbbell-romanian-deadlift','Peso Muerto Rumano a Una Pierna con Mancuerna a Un Brazo','Un peso muerto rumano a una pierna sosteniendo una mancuerna en una sola mano, generalmente la opuesta a la pierna de apoyo (contralateral). Carga los isquiotibiales y glúteos de la pierna de apoyo mientras exige una fuerte contención anti-rotación del core.','De pie sobre una pierna, sostén una mancuerna en la mano contraria. Brazo libre al costado para equilibrarte, pierna libre suspendida justo por encima del suelo. Bisagra en la cadera de apoyo empujándola hacia atrás mientras la pierna libre se extiende detrás para contrarrestar el peso. Mantén las caderas cuadradas al suelo; no las abras hacia el lado. Baja la mancuerna hacia el pie de la pierna de apoyo sintiendo un estiramiento profundo en los isquiotibiales. Impulsa la cadera hacia adelante para volver a ponerte de pie con control. Completa todas las repeticiones de un lado y luego cambia.','strength','compound','advanced',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000191','one-arm-single-leg-kettlebell-romanian-deadlift','Peso Muerto Rumano a Una Pierna con Pesa Rusa a Un Brazo','La versión con pesa rusa del peso muerto rumano a una pierna y un brazo. La masa excéntrica de la pesa rusa y su centro de gravedad más bajo lo convierten en un reto sutilmente diferente al de la mancuerna; excelente para la fuerza de la cadena posterior y el equilibrio bajo carga asimétrica.','De pie sobre una pierna, sostén una pesa rusa en la mano contraria por el asa. Brazo libre al costado para equilibrarte, pierna libre suspendida detrás. Bisagra en la cadera de apoyo empujándola hacia atrás mientras la pierna libre se extiende para contrarrestar el peso. Mantén las caderas cuadradas al suelo; la pesa rusa desciende recto por la espinilla. Siente un estiramiento profundo en los isquiotibiales de la pierna de apoyo en la parte inferior. Impulsa la cadera hacia adelante para volver a ponerte de pie. Completa todas las repeticiones de un lado y luego cambia.','strength','compound','advanced',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000192','overhead-tricep-extension','Extensión de Tríceps por Encima de la Cabeza','Un ejercicio de aislamiento para el tríceps que enfatiza la cabeza larga.','De pie o sentado, sostén una mancuerna por encima de la cabeza con ambas manos. Baja la mancuerna detrás de la cabeza doblando los codos. Extiende los brazos de vuelta a la posición inicial. Mantén los codos cerca de la cabeza durante todo el ejercicio. Repite.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000193','overhead-triceps-stretch','Estiramiento de Tríceps sobre la Cabeza','Un estiramiento de pie que alarga el tríceps y el dorsal llevando la mano por la espalda alta.','Sube un brazo sobre la cabeza y flexiona el codo. Deja caer la mano por detrás de la cabeza. Con la otra mano empuja el codo flexionado hacia atrás. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000194','pigeon-stretch','Estiramiento de la Paloma','Un estiramiento sentado en el suelo para los glúteos y la cadera externa, con la espinilla delantera cruzada al frente.','Desde cuadrupedia, lleva una rodilla adelante y apoya la espinilla cruzada al frente. Extiende la otra pierna recta hacia atrás, con el empeine en el suelo. Baja la cadera hacia el suelo y mantenla cuadrada. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000195','pike-push-ups','Flexiones en Pica','Una flexión realizada con las caderas elevadas en posición de pica, empujando en un ángulo pronunciado para cargar los hombros.','Comienza en posición de perro boca abajo con las caderas altas y las manos a la anchura de los hombros. Acerca los pies a las manos. Dobla los codos y baja la cabeza hacia el suelo. Mantén las caderas altas durante todo el ejercicio. Empuja hacia arriba hasta que los brazos queden completamente extendidos. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000196','pilates-kneeling-side-kick','Patada Lateral de Rodillas de Pilates','Un ejercicio clásico de suelo: de rodillas con la mano apoyada en el suelo, la pierna de arriba oscila adelante y atrás a la altura de la cadera mientras el tronco permanece inmóvil.','Arrodíllate y apoya en el suelo la mano del mismo lado, con la otra mano detrás de la cabeza. Extiende la pierna de arriba hacia el lado a la altura de la cadera, con el pie en flexión. Mantén el tronco completamente quieto y lleva la pierna hacia delante mientras la pelvis siga cuadrada. Lleva la pierna por detrás de la línea del cuerpo sin arquear la zona lumbar. Repite las veces indicadas y cambia de lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000197','pilates-leg-pull-back','Leg Pull Back de Pilates','Una plancha invertida con elevaciones alternas de pierna: las caderas se mantienen altas mientras se eleva una pierna cada vez, de modo que glúteos y parte posterior del tronco trabajan ante el apoyo cambiante.','Siéntate con las piernas estiradas y las manos en el suelo detrás de las caderas, con los dedos hacia delante. Empuja con manos y talones y eleva las caderas a una plancha invertida. Con las caderas niveladas y altas, eleva una pierna estirada mientras la pelvis siga quieta. Baja la pierna de forma controlada y repite con la otra. Termina la serie y baja las caderas al suelo.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000198','pilates-leg-pull-front','Leg Pull Front de Pilates','Una plancha alta con elevaciones alternas de pierna: los hombros permanecen sobre las muñecas mientras se eleva una pierna cada vez, lo que añade una demanda antirrotación a la plancha.','Colócate en plancha alta con las manos bajo los hombros y el cuerpo en línea. Aprieta el tronco y los glúteos para que las caderas no puedan rotar. Eleva una pierna estirada unos centímetros por encima de la cadera sin que la pelvis se incline. Bájala de forma controlada y repite con la otra pierna. Sigue alternando las veces indicadas.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000199','pilates-roll-down','Roll Down de Pilates','Una articulación de la columna de pie: la cabeza guía un descenso vértebra a vértebra hacia el suelo y de vuelta, movilizando toda la espalda mientras las piernas se mantienen estables.','Ponte de pie con los pies a la anchura de las caderas y los brazos colgando a los lados. Lleva la barbilla al pecho y empieza a rodar hacia abajo vértebra a vértebra. Deja los brazos y la cabeza colgando pesados cuando la columna esté completamente descendida. Sube por el mismo camino, apilando las vértebras una a una, la cabeza al final. Repite las veces indicadas.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000200','pilates-roll-over','Roll Over de Pilates','Una inversión controlada desde la colchoneta: con los brazos presionando el suelo, las piernas estiradas viajan por encima de la cabeza hasta que los pies apuntan al suelo, y después la columna vuelve a bajar segmento a segmento.','Túmbate boca arriba con las piernas estiradas y los brazos presionando la colchoneta a los lados. Eleva ambas piernas a la vertical sin dejar que la zona lumbar se arquee. Presiona los brazos hacia abajo y lleva las piernas por encima de la cabeza hasta dejarlas paralelas al suelo por detrás. Abre un poco las piernas, flexiona los pies y baja la columna vértebra a vértebra. Devuelve las piernas a la vertical y repite las veces indicadas.','strength','compound','advanced',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000201','pilates-saw','La Sierra de Pilates','Un giro con flexión sentado: sentado erguido con las piernas abiertas, el torso rota y después se pliega sobre la pierna contraria para que la mano que alcanza pase junto al dedo meñique como una sierra.','Siéntate erguido con las piernas estiradas y algo más abiertas que las caderas, los brazos hacia los lados. Rota el torso hacia un lado manteniendo ambos isquiones en el suelo. Pliégate hacia delante sobre esa pierna y alcanza con la mano contraria más allá del dedo meñique. Vuelve a subir a través de la columna y regresa al centro. Repite hacia el otro lado y sigue alternando.','stretching','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000202','pilates-side-bend','Flexión Lateral de Pilates','Un ejercicio lateral del tronco desde un apoyo de costado: las caderas se elevan y el brazo de arriba se estira por encima de la cabeza, curvando el cuerpo de lado sobre el brazo de apoyo.','Siéntate sobre una cadera con las piernas dobladas hacia un lado y la mano de apoyo en el suelo bajo el hombro. Empuja con la mano y la pierna inferior para elevar las caderas del suelo. Estira el brazo de arriba por encima de la cabeza para formar un arco largo desde la mano hasta los pies. Baja las caderas de forma controlada hacia la colchoneta. Completa las repeticiones y cambia de lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000203','pilates-spine-stretch-forward','Spine Stretch Forward de Pilates','Una articulación sentada: sentado erguido con las piernas abiertas, la columna se enrolla hacia delante segmento a segmento sobre las piernas y después vuelve a apilarse vértebra a vértebra.','Siéntate erguido con las piernas estiradas y algo más abiertas que las caderas, los pies en flexión. Estira los brazos hacia delante a la altura de los hombros. Baja la barbilla y enrolla la columna hacia delante vértebra a vértebra, alcanzando más allá de los pies. Vuelve a apilar la columna desde la base hasta quedar sentado erguido. Repite las veces indicadas.','stretching','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000204','pilates-spine-twist','Spine Twist de Pilates','Una rotación sentada con las piernas juntas y los brazos abiertos: el tronco gira a cada lado de forma controlada mientras la pelvis y las piernas permanecen completamente quietas.','Siéntate erguido con las piernas estiradas y juntas, los pies en flexión y los brazos abiertos a la altura de los hombros. Crece a través de la columna y presiona ambos isquiones contra el suelo. Rota el tronco hacia un lado mientras las caderas sigan cuadradas y vuelve al centro. Rota hacia el otro lado del mismo modo. Sigue alternando las veces indicadas.','stretching','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000205','pistol-squat','Sentadilla a una Pierna (Pistol)','Una sentadilla a una pierna con la pierna libre extendida adelante, que exige fuerza y equilibrio.','Mantente sobre una pierna, la otra extendida al frente, brazos al lado para equilibrio. Flexiona la cadera y la rodilla de apoyo, manteniendo el pecho arriba. Baja lentamente hasta que la parte posterior del muslo toque la pantorrilla. Empuja con el talón de apoyo para volver a subir. Repeticiones por lado, luego cambia de pierna.','strength','compound','advanced',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000206','planche','Plancha Calisténica','Una posición avanzada de calistenia que requiere una fuerza excepcional del tren superior y el core para mantener el cuerpo paralelo al suelo.','Comienza en posición de flexión con las manos giradas hacia afuera. Inclínate hacia adelante hasta que tu centro de masa quede sobre las manos. Levanta los pies del suelo manteniendo el cuerpo horizontal. Mantén la posición. Regresa al suelo con control.','strength','compound','advanced',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000207','plank','Plancha','Un ejercicio isométrico de core que fortalece toda la zona media.','Apoya los antebrazos en el suelo con los codos bajo los hombros. Extiende las piernas hacia atrás y apóyate sobre los dedos de los pies. Mantén el cuerpo en línea recta de la cabeza a los talones. Contrae el core y aprieta los glúteos. Mantén la posición durante el tiempo deseado. Baja las rodillas para salir de la posición.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000208','plank-knee-tuck','Rodilla al Pecho en Plancha','Un ejercicio dinámico de core desde la plancha alta: el cuerpo mantiene su línea recta mientras una rodilla se lleva bajo el pecho y vuelve al inicio, alternando lados. Más lento y controlado que un escalador, trabaja el abdomen y los flexores de cadera mientras hombros y tronco permanecen firmes.','Colócate en plancha alta con las manos bajo los hombros y el cuerpo en línea recta de la cabeza a los talones. Empuja el suelo y aprieta el tronco para que la cadera no se hunda ni se eleve. Lleva una rodilla hacia el pecho sin dejar que la cadera suba. Extiende la pierna de vuelta a la posición inicial de forma controlada. Repite con la otra pierna y sigue alternando las veces indicadas.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000209','plow-pose','Postura del Arado','Una inversión en la que las piernas pasan por encima de la cabeza hasta que los dedos de los pies llegan al suelo por detrás, alargando toda la parte posterior del cuerpo.','Túmbate boca arriba con los brazos junto al cuerpo y las palmas hacia abajo. Eleva ambas piernas por encima de la cabeza y sostén la zona lumbar con las manos. Baja los dedos de los pies hacia el suelo por detrás de la cabeza, con las piernas tan estiradas como resulte cómodo. Mantén la posición durante el tiempo indicado, respirando con calma y sin mover la cabeza. Desciende vértebra a vértebra con las manos sosteniendo la espalda.','stretching','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000210','plyo-lunge','Zancada Pliométrica','Un salto explosivo en posición de zancada que cambia las piernas en el aire, alternando cada repetición.','Comienza en una zancada con un pie adelantado. Baja a una zancada profunda con la rodilla trasera casi tocando el suelo. Despega ambos pies y cambia las piernas en el aire. Aterriza suave en zancada con la pierna opuesta adelante. Continúa alternando sin pausa.','plyometrics','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000211','plyo-push-up','Flexión Pliométrica','Una flexión explosiva en la que las manos despegan del suelo al subir, entrena potencia del tren superior.','Colócate en posición de flexión estándar, manos a la anchura de los hombros. Baja con control hasta que el pecho casi toque el suelo. Empuja explosivamente para que las manos despeguen del suelo. Aterriza suave con los codos ligeramente flexionados. Repite sin pausa el número de repeticiones indicado.','plyometrics','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000212','pseudo-planche-push-ups','Push-Ups de Pseudo Plancha','Una flexión con las manos giradas hacia atrás y los hombros inclinados muy por delante de las muñecas, imitando la carga de la plancha.','Comienza en posición de push-up con las manos giradas de modo que los dedos apunten hacia atrás. Inclina los hombros hacia adelante por delante de las muñecas. Baja el pecho hacia el suelo flexionando los codos. Mantén el cuerpo en línea recta. Empuja hacia arriba manteniendo la inclinación hacia adelante. Repite el número deseado de repeticiones.','strength','compound','advanced',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000213','puppy-pose','Postura del Cachorro','Una postura de rodillas a medio camino entre la postura del niño y el perro boca abajo: las caderas quedan sobre las rodillas mientras el pecho se acerca al suelo, abriendo hombros y espalda alta.','Colócate a cuatro apoyos con las caderas sobre las rodillas y las manos bajo los hombros. Camina las manos hacia delante y baja el pecho hacia el suelo manteniendo las caderas altas. Apoya la frente o la barbilla en la esterilla y deja que las axilas se ablanden hacia abajo. Mantén la posición durante el tiempo indicado, respirando hacia la espalda alta. Camina las manos de vuelta y siéntate sobre los talones para salir.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000214','push-up','Push-Up','Un ejercicio fundamental con el peso corporal para el pecho, los hombros y los tríceps.','Comienza en posición de plancha alta con las manos a la anchura de los hombros. Baja el cuerpo hasta que el pecho casi toque el suelo. Empuja hacia arriba hasta la posición inicial. Mantén el cuerpo en línea recta en todo momento. Repite.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000215','pyramid-pose','Postura de la Pirámide','Una flexión de pie sobre la pierna delantera estirada en un paso corto, que aísla el isquiotibial de esa pierna mientras ambas caderas quedan cuadradas.','Lleva un pie atrás cerca del largo de una pierna y gíralo ligeramente hacia fuera. Cuadra ambas caderas hacia el frente de la esterilla y mantén las dos piernas estiradas. Bascula desde las caderas y flexiona sobre la pierna delantera, llevando las manos al suelo, a bloques o a la espinilla. Mantén la flexión durante el tiempo indicado, con la columna larga en lugar de redondeada. Empuja con los pies para subir y repite del otro lado.','stretching','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000216','rear-delt-fly','Apertura de Deltoides Posterior','Un movimiento de aislamiento que trabaja los deltoides posteriores y la parte superior de la espalda.','Sostén las mancuernas e inclínate hacia adelante desde las caderas. Con una ligera flexión en los codos, eleva las mancuernas hacia los lados. Aprieta las escápulas en la parte superior. Baja con control. Repite.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000217','renegade-row','Remo Renegado','Un ejercicio de remo desde la plancha en el que se rema alternativamente con una mancuerna en cada mano hacia la cadera mientras la otra mano permanece apoyada. Trabaja la espalda y los brazos mientras el tronco resiste la rotación.','Colócate en plancha alta con una mano sobre cada una de dos mancuernas, a la anchura de los hombros, y los pies bien separados para mayor estabilidad. Aprieta el tronco para que el cuerpo forme una línea recta de la cabeza a los talones. Rema una mancuerna hacia la cadera llevando el codo hacia atrás a lo largo de las costillas. Mantén la cadera cuadrada respecto al suelo y no dejes que el cuerpo gire. Baja la mancuerna al suelo de forma controlada. Repite del otro lado y sigue alternando.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000218','reverse-crunches','Crunches Inversos','Un ejercicio de core en el suelo que enrolla la cadera hacia el pecho para trabajar la parte baja del abdomen.','Túmbate boca arriba con los brazos a los lados. Eleva las piernas con las rodillas flexionadas a 90 grados. Despega las caderas del suelo contrayendo el abdomen inferior. Lleva las rodillas hacia el pecho. Baja las caderas con control. Repite el número deseado de repeticiones.','strength','isolation','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000219','reverse-lunge','Zancada Inversa','Una variación de la zancada que da un paso hacia atrás para mayor estabilidad de rodilla.','Párate sosteniendo mancuernas a los costados. Da un paso hacia atrás con una pierna y baja la rodilla hacia el suelo. Baja hasta que el muslo delantero quede paralelo al suelo. Empuja con el talón delantero para volver a la posición de pie. Repite en ambos lados.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000220','reverse-nordic-curl','Nordic Curl Inverso','Un ejercicio de cuádriceps con el propio peso corporal, arrodillado, inclinando el torso hacia atrás con control mientras se mantiene la cadera extendida.','Arrodíllate sobre una almohadilla con las rodillas a la anchura de las caderas, las tibias y el empeine en el suelo y el torso erguido. Mantén la cadera extendida y el core activado. Inclina el torso lentamente hacia atrás manteniendo el cuerpo en línea recta. Baja tanto como puedas controlar con el cuádriceps. Vuelve a subir a la posición inicial. Repite el número de repeticiones deseado.','strength','isolation','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000221','reverse-plank','Plancha Inversa','Una plancha invertida isométrica con el pecho hacia arriba, que fortalece los glúteos y los erectores de la columna.','Siéntate en el suelo con las piernas extendidas al frente. Coloca las manos detrás de ti con los dedos apuntando hacia los pies. Eleva las caderas del suelo para formar una línea recta de la cabeza a los talones. Aprieta los glúteos y contrae el core. Mantén la posición durante el tiempo deseado. Baja las caderas con control para salir.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000222','reverse-plank-dips','Fondos en Plancha Invertida','Fondos de tríceps desde una plancha invertida con las piernas estiradas: las piernas permanecen largas y las caderas altas mientras los codos se flexionan y estiran.','Siéntate con las piernas estiradas y las manos en el suelo detrás de las caderas, con los dedos hacia delante. Empuja con manos y talones y eleva las caderas a una plancha invertida con las piernas estiradas. Flexiona los codos hacia atrás y baja un poco las caderas hacia el suelo. Empuja de nuevo hasta bloquear los brazos, manteniendo las caderas altas. Repite las veces indicadas.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000223','revolved-chair-pose','Postura de la Silla Girada','La postura de la silla con una torsión cerrada: las caderas se mantienen bajas y niveladas mientras el pecho rota y un codo se engancha por fuera del muslo contrario.','Colócate en la postura de la silla con las rodillas flexionadas, las caderas atrás y las palmas juntas frente al pecho. Mantén las rodillas a la misma altura para que las caderas no se abran hacia la torsión. Gira el pecho hacia un lado y engancha el codo contrario por fuera de ese muslo. Presiona las palmas entre sí y mantén durante el tiempo indicado, alargando la columna en cada inhalación. Vuelve al centro y repite del otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000224','revolved-crescent-lunge','Zancada Alta Girada','Una zancada alta con torsión cerrada: el talón trasero sigue elevado, las caderas miran al frente y el pecho rota sobre el muslo delantero.','Colócate en zancada alta con la rodilla delantera sobre el tobillo y el talón trasero elevado. Junta las palmas frente al pecho y cuadra ambas caderas hacia el frente de la esterilla. Gira el pecho hacia la pierna delantera y engancha el codo contrario por fuera del muslo. Mantén la torsión durante el tiempo indicado, empujando el talón trasero hacia la pared de detrás. Deshaz la torsión y repite del otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000225','running','Correr','Carrera al aire libre, con una fase de vuelo en cada zancada en la que ningún pie toca el suelo — el impacto y el esfuerzo que la separan de caminar.','Empieza con un trote suave y sube hasta tu ritmo durante los primeros minutos, en lugar de salir directamente a la velocidad objetivo. Apoya el pie bajo la cadera, no por delante del cuerpo, y mantén el contacto con el suelo corto y silencioso. Corre erguido desde la cadera, con una ligera inclinación desde los tobillos y sin doblarte por la cintura. Flexiona los codos unos noventa grados y lleva los brazos adelante y atrás, sin cruzarlos sobre el pecho. Respira con ritmo y mantén sueltos los hombros, la mandíbula y las manos. Sostén el ritmo el tiempo o la distancia deseados, luego trota y camina unos minutos para terminar.','cardio','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000226','russian-twist','Giro Ruso','Un ejercicio de core rotacional que trabaja los oblicuos.','Siéntate en el suelo con las rodillas flexionadas e inclínate ligeramente hacia atrás. Junta las manos o sostén un peso a la altura del pecho. Rota el torso hacia un lado, luego hacia el otro. Mantén el core apretado en todo momento. Repite.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000227','scissor-kicks','Tijeras','Un ejercicio de core realizado boca arriba, cruzando alternadamente las piernas rectas para trabajar el abdomen bajo y los flexores de cadera.','Recuéstate boca arriba con las manos bajo los glúteos. Eleva ambas piernas unos centímetros del suelo. Cruza alternadamente una pierna sobre la otra en un movimiento de tijera. Mantén la zona lumbar presionada contra el suelo. Mantén un ritmo constante durante todo el ejercicio. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000228','seated-forward-fold','Flexión Sentado hacia Adelante','Un estiramiento sentado para los isquiotibiales y la zona lumbar, inclinando el torso sobre las piernas estiradas.','Siéntate en el suelo con ambas piernas estiradas al frente. Mantén la espalda larga e inclínate desde las caderas. Lleva las manos hacia los pies. Mantén de 20 a 30 segundos, respirando de forma constante.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000229','seated-spinal-twist','Giro Espinal Sentado','Una rotación sentada que estira los oblicuos, la espalda media y los glúteos girando hacia una rodilla flexionada.','Siéntate con una pierna estirada y cruza el otro pie por encima. Apoya el codo opuesto contra la parte externa de la rodilla flexionada. Gira el torso hacia la rodilla flexionada y mira sobre el hombro. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000230','seated-straddle-stretch','Estiramiento en Apertura Sentado','Un estiramiento sentado con piernas abiertas para aductores e isquiotibiales, inclinando el torso entre las piernas.','Siéntate con las piernas estiradas y bien abiertas en V. Mantén la espalda larga e inclínate desde las caderas. Camina las manos hacia adelante por el suelo. Mantén de 20 a 30 segundos, respirando de forma constante.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000231','side-lunge','Zancada Lateral','Una zancada lateral que da un paso amplio hacia un lado, trabajando los cuádriceps, glúteos y la cara interna de los muslos en un patrón lateral.','De pie con los pies al ancho de las caderas y las manos en el pecho. Da un paso amplio hacia un lado con una pierna, manteniendo la otra recta. Flexiona la rodilla de la pierna que dio el paso y empuja las caderas hacia atrás en una sentadilla lateral. Mantén el pecho erguido y el talón de trabajo apoyado. Empuja con la pierna flexionada para volver a la posición de pie. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000232','side-lying-hip-abduction','Abducción de Cadera Acostado de Lado','Un ejercicio de aislamiento con peso corporal que trabaja el glúteo medio y los abductores de cadera.','Acuéstate de lado con las piernas apiladas. Mantén la pierna inferior ligeramente flexionada. Eleva la pierna superior hacia el techo. Baja con control. Repite de ambos lados.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000233','side-lying-hip-abduction-hold','Abducción de Cadera Acostado de Lado Isométrica','La parte alta de la elevación lateral de pierna mantenida en el tiempo: tumbado de lado con la pierna superior elevada y ligeramente por detrás del cuerpo, cargando el glúteo medio de forma isométrica.','Túmbate de lado con las piernas estiradas y apiladas, apoyando la cabeza sobre el brazo inferior. Aprieta el tronco para que el torso quede cuadrado y no ruede hacia atrás. Eleva la pierna superior unos 30 o 45 grados, con los dedos del pie apuntando al frente. Mantén la pierna ahí durante el tiempo indicado, respirando con normalidad. Baja la pierna de forma controlada y repite del otro lado.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000234','side-lying-hip-adduction','Aducción de Cadera Acostado de Lado','Un ejercicio de aducción tumbado de lado que eleva la pierna inferior contra la gravedad para trabajar la cadera con el propio peso.','Acuéstate de lado con la pierna inferior recta. Flexiona la pierna superior y coloca su pie plano frente al muslo inferior. Apoya la cabeza con el brazo inferior. Eleva la pierna inferior hacia el techo. Baja la pierna con control. Completa las repeticiones de un lado y luego cambia.','strength','isolation','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000235','side-lying-hip-adduction-hold','Aducción de Cadera Acostado de Lado Isométrica','La parte alta de la elevación de cara interna del muslo mantenida en el tiempo: tumbado de lado con la pierna superior cruzada por delante y la pierna inferior separada del suelo por los aductores.','Túmbate de lado con la pierna inferior estirada y la superior cruzada por encima, con el pie apoyado en el suelo. Apoya la cabeza sobre el brazo inferior y mantén las caderas apiladas en vertical. Eleva la pierna inferior todo lo que puedas con la rodilla estirada y los dedos del pie al frente. Mantén esa posición elevada durante el tiempo indicado sin rodar la cadera hacia atrás. Baja la pierna de forma controlada y repite del otro lado.','strength','isolation','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000236','side-plank','Plancha Lateral','Una variación de plancha lateral que trabaja los oblicuos y el core lateral.','Acuéstate de lado con el antebrazo en el suelo y el codo bajo el hombro. Levanta las caderas del suelo formando una línea recta de la cabeza a los pies. Mantén la posición con el core apretado. Respira con regularidad. Repite de ambos lados.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000237','side-plank-leg-lift-hold','Plancha Lateral con Elevación de Pierna Isométrica','Una plancha lateral sostenida con la pierna superior elevada: la cadera se mantiene alta y cuadrada mientras la pierna se separa, lo que añade una demanda de glúteo medio al trabajo lateral del tronco.','Colócate en plancha lateral sobre el antebrazo, con el codo bajo el hombro y los pies apilados. Eleva la cadera hasta que el cuerpo forme una línea recta desde los tobillos hasta la cabeza. Sube la pierna superior aproximadamente a la altura de la cadera, con los dedos del pie al frente. Mantén la posición durante el tiempo indicado, con la cadera alta y el hombro alineado sobre el codo. Baja la pierna y la cadera de forma controlada y repite del otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000238','single-arm-dumbbell-overhead-tricep-extension','Extensión de Tríceps sobre la Cabeza con Mancuerna a Un Brazo','Una extensión de tríceps sobre la cabeza a un brazo que proporciona un estiramiento largo y unilateral de la cabeza larga y entrena la estabilidad del core contra la flexión lateral.','De pie o sentado, sostén una mancuerna en una mano sobre la cabeza con el brazo completamente extendido. La palma mira hacia adelante; la otra mano puede apoyarse en la cadera o en un soporte para mayor estabilidad. Flexiona el codo para bajar la mancuerna detrás de la cabeza en un arco controlado. Mantén el brazo superior vertical y cerca de la cabeza durante todo el movimiento. Extiende el codo para regresar la mancuerna sobre la cabeza. Completa todas las repeticiones de un lado y luego cambia.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000239','single-arm-hammer-curl','Curl martillo unilateral','Un curl unilateral con mancuerna y agarre neutro que mantiene el codo de trabajo junto al torso mientras el braquial y el braquiorradial flexionan el codo.','Colócate con los pies al ancho de las caderas y sostén una mancuerna al costado con la palma hacia dentro. Activa el tronco y mantén el brazo de trabajo junto a las costillas mientras cuelga extendido. Lleva la mancuerna hacia el hombro sin girar la palma ni balancear el torso. Aprieta los flexores del codo arriba y baja la mancuerna de forma controlada hasta extender el brazo. Completa las repeticiones de un lado y después cambia de brazo.','strength','isolation','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000240','single-db-svend-press','Press Svend con una Mancuerna','Un press de pecho de pie sosteniendo una sola mancuerna en vertical entre las palmas, donde lo que trabaja los pectorales es la presión hacia adentro y no la carga.','De pie y erguido, sostén una sola mancuerna en vertical frente al esternón, con el mango entre las palmas planas. Aprieta con fuerza las palmas contra la mancuerna para que la tensión vaya al pecho y el peso no resbale. Empuja la mancuerna recto hacia adelante hasta que los brazos queden casi estirados, manteniéndola a la altura del pecho todo el recorrido. Haz una breve pausa sin soltar la presión y devuelve la mancuerna al pecho con control. Repite el número de repeticiones recomendado.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000241','single-leg-calf-raise','Elevación de Pantorrilla a Una Pierna','Una elevación de pantorrilla unilateral que carga una pantorrilla a la vez y expone desequilibrios laterales.','Mantente sobre un pie con la punta sobre una plataforma elevada, talón al aire. Sujétate a una pared o barandilla con una mano para equilibrio. Baja el talón por debajo de la plataforma para un estiramiento profundo. Empuja arriba sobre la punta tan alto como puedas. Baja con control. Repeticiones por lado, luego cambia.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000242','single-leg-glute-bridge','Puente de Glúteo a Una Pierna','Un puente de glúteo unilateral que carga un glúteo a la vez y ayuda a corregir desequilibrios laterales.','Acuéstate boca arriba con una rodilla flexionada y el pie plano, la otra pierna extendida recta. Activa el core y contrae el glúteo del lado que trabaja. Empuja las caderas arriba presionando con el talón de trabajo. Pausa arriba con el cuerpo en línea recta de hombros a rodilla. Baja con control. Repeticiones por lado, luego cambia.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000243','single-leg-glute-bridge-hold','Puente de Glúteo a Una Pierna Isométrico','La parte alta del puente de glúteo a una pierna mantenida en el tiempo: la cadera queda extendida y nivelada mientras una pierna permanece elevada, de modo que un solo glúteo sostiene toda la posición.','Túmbate boca arriba con una rodilla flexionada y ese pie apoyado, y eleva la otra pierna hasta que el muslo quede casi vertical. Empuja con el talón del pie apoyado y eleva la cadera hasta que el cuerpo quede recto desde la rodilla hasta los hombros. Nivela la pelvis para que el lado elevado no caiga y lleva las costillas hacia abajo. Mantén la posición alta durante el tiempo indicado, con la rodilla elevada quieta. Baja la cadera de forma controlada y repite del otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000244','single-leg-rdl-hold','Peso Muerto Rumano a Una Pierna Isométrico','Un mantenimiento de equilibrio en la parte baja de un peso muerto rumano a una pierna: de pie sobre una pierna, el torso se inclina hacia delante y la otra pierna se extiende hacia atrás en línea con el cuerpo. Entrena los isquiotibiales, los glúteos y el tronco mientras desafía el equilibrio.','Colócate sobre una pierna con una ligera flexión de rodilla y los brazos colgando delante de ti. Haz una bisagra de cadera, enviando la pierna libre recta hacia atrás mientras el torso se inclina hacia delante. Mantén la espalda plana y la cadera cuadrada respecto al suelo. Detente cuando el torso y la pierna libre queden aproximadamente paralelos al suelo y mantén la posición. Vuelve a ponerte de pie de forma controlada y luego cambia de pierna.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000245','single-leg-romanian-deadlift','Peso Muerto Rumano a Una Pierna','Un peso muerto rumano a una pierna con mancuernas, que trabaja isquiotibiales y glúteos mientras exige equilibrio y estabilidad de cadera.','Apóyate en una pierna sosteniendo una mancuerna en cada mano frente a los muslos. Mantén una ligera flexión en la rodilla de apoyo. Bisagra en la cadera extendiendo la pierna libre detrás. Baja las mancuernas a lo largo de la pierna de apoyo hasta sentir el estiramiento en los isquiotibiales. Empuja con el talón para volver a la posición erguida. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000246','sit-ups','Abdominales','Un ejercicio abdominal clásico con rango de movimiento completo.','Acuéstate boca arriba con las rodillas flexionadas y los pies anclados. Cruza los brazos sobre el pecho o coloca las manos detrás de la cabeza. Siéntate completamente hasta que el torso quede erguido. Baja con control. Repite.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000247','six-inch-hold','Mantenimiento a 15 cm del Suelo','Un mantenimiento estático de core tumbado boca arriba con la cabeza, los hombros y las piernas rectas elevados unos 15 cm del suelo. Entrena la parte baja del abdomen y los flexores de cadera.','Túmbate boca arriba con las piernas estiradas y los brazos descansando a lo largo de los costados. Presiona la zona lumbar contra el suelo y contrae el abdomen. Levanta la cabeza, los hombros y las piernas rectas unos 15 cm del suelo. Mantén la posición respirando con regularidad. Baja despacio para descansar.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000248','sphinx-pose','Postura de la Esfinge','Una extensión suave boca abajo sobre los antebrazos: los codos quedan bajo los hombros y el pecho se eleva, de modo que la zona lumbar se extiende sin esfuerzo de los brazos.','Túmbate boca abajo y apoya los antebrazos en el suelo con los codos justo bajo los hombros. Presiona los antebrazos y el empeine contra el suelo y eleva el pecho. Aleja los hombros de las orejas y alarga la nuca. Mantén la posición durante el tiempo indicado, respirando hacia la parte frontal del pecho. Baja el pecho al suelo y descansa.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000249','spiderman-push-up','Flexión Spiderman','Una flexión en la que se lleva una rodilla hacia el codo del mismo lado mientras el cuerpo baja, como una araña trepando por una pared. Trabaja el pecho, los hombros y los tríceps, mientras los oblicuos y los flexores de cadera mantienen estable el tronco.','Colócate en plancha alta con las manos algo más abiertas que los hombros y el cuerpo en línea recta. Empieza a bajar el pecho hacia el suelo y, al mismo tiempo, levanta un pie del suelo. Lleva esa rodilla hacia fuera y arriba, hacia el codo del mismo lado, manteniendo la cadera baja. Empuja para volver a la plancha mientras devuelves la pierna a la posición inicial. Repite del otro lado y sigue alternando.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000250','split-squat','Sentadilla en Tijera','Una zancada estática bajando en línea recta con las piernas en tijera, desarrollando fuerza unilateral sin dar el paso.','Párate en posición de tijera con un pie adelante y otro atrás. Mantén el torso erguido y el core contraído. Baja las caderas rectas hacia abajo doblando ambas rodillas. Detente cuando la rodilla trasera esté justo por encima del suelo. Empuja a través del talón delantero para volver al inicio. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000251','squat-hold','Sentadilla Isométrica','Una sentadilla estática en la que se mantienen los muslos aproximadamente paralelos al suelo y los brazos estirados al frente para mantener el equilibrio. Desarrolla resistencia en los cuádriceps y los glúteos sin equipo.','Colócate de pie con los pies a la anchura de los hombros y las puntas ligeramente hacia fuera. Estira los brazos rectos al frente como contrapeso. Baja en sentadilla hasta que los muslos queden paralelos al suelo, con el pecho erguido y los talones apoyados. Mantén la posición, con las rodillas en línea con las puntas de los pies. Ponte de pie para terminar.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000252','squat-pulse','Sentadilla con Pulsos','Una variante de la sentadilla con el peso corporal en la que bajas a la sentadilla y haces pulsos cortos y controlados, hacia arriba y hacia abajo, en la mitad inferior del movimiento sin llegar a ponerte de pie. La tensión constante mantiene trabajando los muslos y los glúteos durante toda la serie.','Colócate de pie con los pies separados a la anchura de los hombros aproximadamente y las puntas ligeramente hacia fuera, con los brazos estirados al frente para mantener el equilibrio. Baja en sentadilla hasta que los muslos queden al menos paralelos al suelo, con el pecho erguido y los talones apoyados. Desde abajo, sube solo un poco, unos pocos centímetros, y vuelve a bajar. Sigue haciendo pulsos en el rango inferior sin extender del todo las piernas ni descansar arriba. Ponte de pie por completo cuando termines la serie.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000253','stability-ball-hip-bridge','Puente de Cadera con Balón de Estabilidad','Un puente de glúteos con los pies sobre un balón de estabilidad, que añade demanda antirotación y de equilibrio al patrón básico del puente.','Túmbate boca arriba en el suelo y coloca ambos pies sobre un balón de estabilidad. Los brazos descansan a los lados en el suelo para equilibrarte. Aprieta los glúteos y presiona los talones contra el balón para elevar las caderas. Termina con una línea recta desde los hombros hasta las rodillas. Baja las caderas de forma controlada sin que el balón ruede. Repite el número de repeticiones recomendado.','strength','isolation','beginner',null,false,true,'stability_ball'),
  ('30000000-0000-4000-8000-000000000254','stability-ball-knee-tuck','Encogimiento de Rodillas con Balón de Estabilidad','Un encogimiento de rodillas en posición de plancha con los pies sobre un balón de estabilidad, rodando el balón hacia las caderas para trabajar el abdomen dinámicamente.','Comienza en plancha alta con las espinillas o el dorso de los pies sobre un balón de estabilidad. Las manos están bajo los hombros y el cuerpo en línea recta. Contrae el core y lleva el balón hacia el pecho encogiendo las rodillas. Rueda de vuelta hacia afuera extendiendo completamente las piernas a la posición de plancha. Repite el número de repeticiones recomendado.','strength','compound','intermediate',null,false,true,'stability_ball'),
  ('30000000-0000-4000-8000-000000000255','stability-ball-push-up','Push-Up con Balón de Estabilidad','Un push-up realizado con los pies sobre un balón de estabilidad, que añade una fuerte demanda antirotación al push-up estándar.','Arrodíllate frente a un balón de estabilidad y coloca las espinillas o los pies encima. Apoya las manos en el suelo bajo los hombros en posición de plancha alta. Contrae fuerte el core: el balón querrá rodar hacia los lados. Baja el pecho al suelo doblando los codos. Vuelve a empujar hasta la posición inicial sin dejar que el balón se tambalee. Repite el número de repeticiones recomendado.','strength','compound','intermediate',null,false,true,'stability_ball'),
  ('30000000-0000-4000-8000-000000000256','stability-ball-push-up-hands-on-ball','Flexión sobre pelota de estabilidad (manos en la pelota)','Una flexión inclinada realizada con ambas manos sobre una pelota de estabilidad y los pies en el suelo. La superficie inestable exige más al pecho, los hombros y los tríceps, mientras el core mantiene el cuerpo rígido.','Coloca ambas manos sobre una pelota de estabilidad y camina con los pies hacia atrás hasta una plancha con los brazos extendidos, el cuerpo en línea recta de la cabeza a los talones. Activa el core y mantén la pelota firme bajo las manos. Flexiona los codos para bajar el pecho hacia la pelota de forma controlada. Empuja de nuevo hasta la extensión completa de los brazos sin dejar que la pelota ruede. Repite las repeticiones deseadas.','strength','compound','intermediate',null,false,true,'stability_ball'),
  ('30000000-0000-4000-8000-000000000257','stability-ball-wall-squat','Sentadilla en Pared con Pelota','Una sentadilla con peso corporal apoyando una pelota suiza entre la zona lumbar y la pared, que guía la columna.','Coloca una pelota suiza entre tu zona lumbar y una pared. Adelanta los pies unos 30 cm, un poco más anchos que los hombros. Baja en sentadilla mientras la pelota rueda por la espalda. Detente cuando los muslos queden paralelos al suelo. Empuja con los talones para volver a subir.','strength','compound','beginner',null,false,true,'stability_ball'),
  ('30000000-0000-4000-8000-000000000258','standing-calf-stretch','Estiramiento de Pantorrilla de Pie','Un estiramiento en paso escalonado que alarga la pantorrilla presionando el talón trasero con la pierna estirada.','Lleva un pie atrás a un paso escalonado. Mantén la pierna trasera estirada y el talón presionado al suelo. Flexiona la rodilla delantera e inclina el peso hacia adelante. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000259','standing-forward-fold','Flexión de Pie hacia Adelante','Un estiramiento de pie que alarga los isquiotibiales y la zona lumbar al inclinar el torso sobre las piernas estiradas.','Párate erguido con los pies al ancho de cadera y las piernas estiradas. Flexiónate desde las caderas y baja el torso hacia el suelo. Deja que las manos y la cabeza cuelguen hacia los pies. Mantén de 20 a 30 segundos, respirando de forma constante.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000260','standing-forward-fold-to-half-lift','Flexión de Pie a Media Elevación','La articulación conocida como media elevación: desde una flexión de pie el pecho sube hasta dejar la espalda plana y la columna larga, y luego vuelve a plegarse. Enseña la diferencia entre una flexión redondeada y una bisagra con la columna larga.','Ponte de pie con los pies a la anchura de las caderas y pliégate hacia delante desde las caderas. Apoya las manos en las espinillas, en el suelo o en bloques. Desliza las manos por las espinillas y eleva el pecho hasta dejar la espalda plana y la columna larga. Vuelve a plegarte dejando que la cabeza y el cuello se relajen. Sigue alternando entre ambas posiciones las veces indicadas.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000261','standing-quad-stretch','Estiramiento de Cuádriceps de Pie','Un estiramiento de equilibrio de pie que alarga el cuádriceps llevando el talón hacia el glúteo.','Párate sobre una pierna, apoyándote en una pared si lo necesitas. Flexiona la otra rodilla y agarra ese tobillo por detrás. Lleva el talón hacia el glúteo, manteniendo las rodillas juntas. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000262','standing-side-bend','Flexión Lateral de Pie','Un estiramiento de pie que alarga los oblicuos y dorsales al estirar los brazos arriba e inclinarse a un lado.','Párate con los pies al ancho de cadera y sube ambos brazos. Junta las manos y estírate hacia arriba. Inclínate suavemente a un lado en una curva larga. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000263','standing-side-bend-flow','Flexión Lateral de Pie Alterna','Un flujo lateral de pie: los brazos se estiran por encima de la cabeza y el tronco se inclina de lado a lado con un ritmo controlado, alargando el costado sin sostener ninguna posición final.','Ponte de pie con los pies a la anchura de las caderas y estira ambos brazos por encima de la cabeza. Inclina el tronco hacia un lado manteniendo los pies apoyados y las caderas niveladas. Vuelve por el centro con las costillas alineadas sobre la pelvis. Inclínate hacia el otro lado del mismo modo. Sigue alternando las veces indicadas.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000264','standing-split','Split de Pie','Una flexión de pie con una pierna elevada por detrás: el torso se pliega sobre la pierna de apoyo mientras la pierna libre se eleva hacia el techo.','Desde una flexión hacia delante, apoya ambas manos en el suelo o en bloques junto al pie de apoyo. Pasa el peso a una pierna y eleva la otra por detrás. Mantén la pierna de apoyo estirada y las caderas tan niveladas como permita la elevación. Mantén la posición durante el tiempo indicado, acercando el pecho a la espinilla de apoyo. Baja el pie elevado y repite del otro lado.','stretching','compound','advanced',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000265','stationary-bike','Bicicleta Estática','Un ejercicio cardiovascular sentado que mueve un volante de inercia mediante un pedaleo continuo, trabajando las piernas sin impacto sobre las articulaciones.','Ajusta la altura del sillín para que la rodilla quede ligeramente flexionada en el punto más bajo del pedaleo, siéntate y apoya la parte anterior de los pies en los pedales. Sujeta el manillar con un agarre relajado y siéntate erguido, con la espalda neutra y los hombros bajos. Empuja un pedal hacia abajo y hacia delante mientras el otro sube, manteniendo el esfuerzo en las piernas en lugar de tirar del manillar. Sigue pedaleando en un círculo suave y regular a una cadencia constante, respirando al ritmo del pedaleo. Ajusta la resistencia para sostener el esfuerzo que buscas y continúa durante el tiempo o la distancia deseados.','cardio','compound','beginner',null,false,true,'stationary_bike'),
  ('30000000-0000-4000-8000-000000000266','strict-curl','Curl Estricto','Un curl de pie realizado sin ningún impulso corporal — el torso permanece quieto y los codos se mantienen fijos, de modo que el bíceps hace todo el trabajo.','Ponte de pie con una mancuerna en cada mano, los brazos a los costados y las palmas hacia adelante. Fija los codos a los costados y contrae el core para que el torso no pueda balancearse. Flexiona ambas mancuernas hacia arriba moviendo solo los codos. Bájalas de forma controlada hasta que los brazos queden rectos. Repite las repeticiones deseadas.','strength','isolation','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000267','suitcase-carry','Paseo del Maletín','Un paseo cargado con el peso en una sola mano, de modo que el tronco tiene que resistir la inclinación lateral durante todo el recorrido — la versión unilateral del paseo del granjero.','Colócate junto a una sola kettlebell o mancuerna, con los pies a la anchura de las caderas. Flexiona por la cadera, agarra el asa con una mano e incorpórate con el peso colgando a un costado. Lleva ese hombro abajo y atrás, y aprieta el tronco como si fueran a empujarte de lado. Camina hacia delante con zancadas normales y regulares, manteniendo el torso erguido y cuadrado en lugar de inclinarte para escapar del peso. Mantén el brazo libre relajado junto al cuerpo, sin separarlo como contrapeso. Carga la distancia o el tiempo deseados, deja el peso en el suelo de forma controlada y repite por el otro lado.','strength','compound','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000268','superman','Superman','Un ejercicio de peso corporal para la zona lumbar realizado en prono, levantando brazos y piernas simultáneamente.','Túmbate boca abajo con los brazos extendidos por encima de la cabeza. Levanta simultáneamente los brazos, el pecho y las piernas del suelo. Mantén brevemente la posición superior. Baja de forma controlada. Repite.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000269','supine-spinal-twist','Giro Espinal Tumbado','Un giro tumbado que estira la zona lumbar, los glúteos y los oblicuos al cruzar una rodilla flexionada sobre el cuerpo.','Acuéstate boca arriba y lleva una rodilla al pecho. Guía esa rodilla cruzando el cuerpo hacia el suelo. Extiende los brazos y gira la cabeza hacia el lado contrario. Mantén de 20 a 30 segundos, respirando de forma constante. Cambia de lado y repite.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000270','supine-windshield-wipers','Limpiaparabrisas Tumbado','Un ejercicio de rotación tumbado: con las rodillas flexionadas o las piernas elevadas, ambas piernas oscilan de lado a lado como limpiaparabrisas mientras los hombros permanecen pegados al suelo.','Túmbate boca arriba con los brazos abiertos a los lados y las rodillas flexionadas sobre las caderas. Aprieta el tronco para que la zona lumbar no se despegue del suelo. Baja ambas piernas juntas hacia un lado mientras los hombros sigan apoyados. Devuélvelas por el centro y bájalas hacia el otro lado. Sigue alternando las veces indicadas.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000271','supported-shoulderstand','Vela con Apoyo','Una inversión apoyada en los hombros y los brazos, con las manos sosteniendo la espalda y el cuerpo alineado en vertical sobre los hombros.','Túmbate boca arriba, idealmente con una manta doblada bajo los hombros y la cabeza fuera de ella. Eleva las piernas por encima de la cabeza y sostén la zona lumbar con ambas manos, los codos a la anchura de los hombros. Camina las manos por la espalda y alinea las caderas sobre los hombros hasta que el cuerpo quede vertical. Mantén la posición durante el tiempo indicado, con la cabeza y el cuello completamente quietos. Baja las piernas por encima de la cabeza y desciende despacio con las manos sosteniendo la espalda.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000272','thoracic-bridge','Puente Torácico','Un sostén de movilidad que eleva las caderas desde sentado, con las manos detrás, hasta una mesa invertida y abre el pecho, extendiendo la columna torácica mientras los glúteos y los hombros sostienen el puente.','Siéntate en el suelo con las rodillas flexionadas y las manos detrás, los dedos apuntando hacia atrás. Empuja con las manos y los pies para elevar las caderas del suelo. Sigue empujando hasta que el pecho se abra y los brazos queden extendidos. Deja caer la cabeza hacia atrás y mantén la posición. Respira de forma constante mientras mantienes el puente. Baja de nuevo de forma controlada.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000273','thread-the-needle','Enhebrar la Aguja','Una rotación de rodillas: un brazo se desliza por debajo del cuerpo y el hombro y el lateral de la cabeza descansan en el suelo, rotando la columna torácica de forma pasiva.','Comienza a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas. Desliza un brazo por debajo del cuerpo con la palma hacia arriba hasta que el hombro y el lateral de la cabeza apoyen en la esterilla. Mantén las caderas sobre las rodillas y camina la mano de arriba hacia delante o llévala a la espalda. Mantén la torsión durante el tiempo indicado, respirando hacia la espalda alta. Presiona la mano de arriba contra el suelo para subir y repite del otro lado.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000274','thread-the-needle-flow','Enhebrar la Aguja Dinámico','La versión en movimiento de enhebrar la aguja: desde cuatro apoyos el brazo pasa por debajo del cuerpo y después se abre hacia el techo, rotando la columna torácica por todo su recorrido.','Comienza a cuatro apoyos con las manos bajo los hombros y las rodillas bajo las caderas. Desliza un brazo por debajo del cuerpo hasta que el hombro se acerque a la esterilla. Invierte el movimiento y abre ese brazo hacia el techo, siguiendo la mano con la mirada. Vuelve por el centro y repite las veces indicadas. Cambia de lado y repite.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000275','three-legged-dog','Perro de Tres Patas','El perro boca abajo con una pierna elevada: los hombros asumen más carga mientras la pierna elevada se alinea con la columna y las caderas se mantienen cuadradas.','Colócate en perro boca abajo con las manos a la anchura de los hombros y las caderas altas. Presiona ambas manos por igual contra el suelo y desplaza el peso ligeramente hacia delante. Eleva una pierna por detrás hasta alinearla con la columna, con ambas caderas niveladas. Mantén la posición durante el tiempo indicado, con el talón de apoyo bajando hacia el suelo. Baja la pierna y repite del otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000276','tree-pose','Postura del Árbol','Un equilibrio de pie sobre una pierna con la planta del pie libre apoyada en la pantorrilla o el muslo interno y las caderas niveladas.','Ponte de pie y pasa el peso a un pie. Apoya la planta del otro pie en la cara interna de la pantorrilla o del muslo, evitando la rodilla. Presiona el pie y la pierna entre sí y nivela las caderas. Lleva las manos al pecho o por encima de la cabeza y mantén durante el tiempo indicado. Baja el pie y repite del otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000277','triangle-pose','Postura del Triángulo','Una postura de base amplia con ambas piernas estiradas y el torso inclinándose lateralmente sobre la pierna delantera, que alarga el isquiotibial y todo el costado.','Sepárate en una base amplia con el pie delantero girado hacia fuera y el trasero algo hacia dentro. Mantén ambas piernas estiradas y estira la mano delantera hacia delante mientras las caderas van atrás. Inclínate lateralmente y lleva la mano de abajo a la espinilla, un bloque o el suelo, con el brazo de arriba hacia el techo. Mantén la posición durante el tiempo indicado, girando el pecho hacia el techo. Empuja con los pies para subir y repite del otro lado.','stretching','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000278','tricep-kickback','Patada de Tríceps con Mancuerna','Un ejercicio de aislamiento para los tríceps realizado en posición inclinada hacia adelante.','Inclínate hacia adelante en las caderas sosteniendo una mancuerna con el codo doblado a 90 grados. Extiende el brazo recto hacia atrás apretando el tríceps. Mantén brevemente en la extensión completa. Baja con control. Repite en ambos lados.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000279','upward-dog','Perro Boca Arriba','Una extensión boca abajo sobre los brazos estirados con los muslos despegados del suelo, donde los brazos y los extensores de la espalda mantienen el pecho abierto y la columna larga.','Túmbate boca abajo con las manos junto a las costillas bajas y el empeine apoyado en el suelo. Presiona las manos y estira los brazos, elevando primero el pecho y después los muslos de la esterilla. Lleva los hombros atrás y abajo y mantén el cuello largo. Mantén la posición durante el tiempo indicado con solo las manos y el empeine en el suelo. Flexiona los brazos y baja de forma controlada.','stretching','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000280','v-sit','Posición en V','Un sostén estático del core en equilibrio sobre los isquiones, con las piernas y el torso elevados formando una V, que exige a los abdominales y los flexores de cadera.','Siéntate en el suelo con las piernas extendidas frente a ti. Inclínate ligeramente hacia atrás y eleva las piernas del suelo. Extiende los brazos hacia adelante para que el cuerpo forme una V. Equilíbrate sobre los isquiones con el core firme. Mantén la posición respirando de forma constante. Baja las piernas y el torso para salir.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000281','v-ups','V-Ups','Un ejercicio dinámico de core que eleva las piernas y el torso juntos formando una V, trabajando los abdominales y los flexores de la cadera.','Túmbate boca arriba con los brazos extendidos por encima de la cabeza y las piernas rectas. Levanta simultáneamente las piernas y la parte superior del cuerpo hacia el centro. Alcanza las manos hacia los pies en la parte superior, formando una V. Mantén las piernas rectas durante todo el movimiento. Baja ambos extremos de forma controlada hasta el suelo. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000282','walking-lunge','Zancada Caminando','Una zancada en movimiento que avanza pierna tras pierna, trabajando los cuádriceps y glúteos con un desafío de equilibrio adicional.','Párate erguido con los pies separados al ancho de las caderas y las manos en las caderas. Da un paso adelante largo con un pie en zancada. Baja hasta que ambas rodillas estén en torno a 90 grados. Empuja con el talón delantero y lleva el pie trasero hacia adelante. Continúa alternando piernas al avanzar. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000283','wall-push-ups','Push-Ups en Pared','Una flexión de pie contra la pared apta para principiantes, que trabaja el pecho con carga reducida.','Párate frente a una pared y coloca las palmas sobre ella a la altura de los hombros. Retrocede con los pies hasta que los brazos estén completamente extendidos. Flexiona los codos para acercar el pecho a la pared. Mantén el cuerpo en línea recta durante todo el movimiento. Empuja de vuelta a la posición inicial. Repite el número de repeticiones deseado.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000284','wall-sit','Sentadilla en Pared','Un ejercicio isométrico estático que consiste en mantener la posición de sentadilla contra una pared para desarrollar la resistencia de los cuádriceps.','Párate con la espalda contra una pared. Deslízate hacia abajo hasta que los muslos estén paralelos al suelo. Mantén la posición. Vuelve a ponerte de pie cuando termines.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000285','warrior-one','Guerrero I','Una postura en paso largo con el pie trasero apoyado en diagonal, la rodilla delantera flexionada y los brazos arriba, con las caderas mirando al frente.','Lleva un pie atrás y gíralo unos cuarenta y cinco grados, apoyando toda la planta. Flexiona la rodilla delantera hasta que quede sobre el tobillo y mantén la pierna trasera estirada. Lleva ambas caderas hacia el frente de la esterilla y eleva los brazos por encima de la cabeza. Mantén la posición durante el tiempo indicado, con las costillas cerradas y el pecho alto. Junta los pies y repite del otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000286','warrior-three','Guerrero III','Un equilibrio sobre una pierna con el torso y la pierna elevada paralelos al suelo, formando una línea larga desde las yemas de los dedos hasta el talón elevado.','Ponte de pie sobre una pierna con la rodilla blanda y las caderas niveladas. Bascula hacia delante desde las caderas mientras la otra pierna se eleva por detrás. Continúa hasta que el torso y la pierna elevada queden aproximadamente paralelos al suelo. Estira los brazos hacia delante, junto al cuerpo o hacia los lados, y mantén durante el tiempo indicado. Baja la pierna y repite del otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000287','warrior-two','Guerrero II','Una postura de base amplia con la rodilla delantera flexionada, las caderas abiertas al lado y los brazos extendidos a la altura de los hombros.','Sepárate en una base amplia con el pie delantero girado noventa grados y el trasero algo hacia dentro. Flexiona la rodilla delantera hasta que quede sobre el tobillo y apunte hacia los dedos centrales. Abre las caderas y el pecho hacia el lado y extiende los brazos paralelos al suelo. Mantén la posición durante el tiempo indicado, con la mirada sobre la mano delantera. Estira la pierna delantera y repite del otro lado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000288','wide-grip-push-ups','Flexiones con Agarre Ancho','Una variante de flexión con las manos colocadas más separadas para enfatizar el pecho.','Comienza en una plancha alta con las manos más separadas que el ancho de hombros. Mantén el cuerpo en línea recta de la cabeza a los talones. Baja el pecho hacia el suelo flexionando los codos. Mantén el core activado y los glúteos contraídos. Empuja de vuelta hasta extender los brazos. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000289','wide-legged-forward-fold','Flexión con Piernas Abiertas','Una flexión de pie desde una base amplia con las manos en el suelo, que alarga los isquiotibiales y la cara interna de los muslos mientras la columna cuelga larga.','Ponte de pie con los pies muy separados y los bordes externos paralelos. Apoya las manos en las caderas, eleva el pecho y bascula hacia delante desde las articulaciones de la cadera. Lleva las manos al suelo bajo los hombros y deja que la cabeza cuelgue. Mantén la flexión durante el tiempo indicado, desplazando ligeramente el peso hacia las puntas de los pies. Devuelve las manos a las caderas y sube con la espalda plana.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000290','zottman-curl','Curl Zottman','Un curl con mancuernas de pie que sube con agarre supinado, gira las palmas hacia abajo en la parte superior y desciende en pronación para combinar el trabajo del bíceps con una fase excéntrica centrada en los antebrazos.','Colócate de pie con los pies aproximadamente al ancho de las caderas, los brazos extendidos a los lados y una mancuerna en cada mano con las palmas hacia delante. Mantén los brazos junto a las costillas y lleva ambas mancuernas hacia los hombros sin balancear el torso. En la parte superior, conserva los codos flexionados y gira los antebrazos hasta que las palmas miren hacia abajo. Baja lentamente las mancuernas con el agarre pronado hasta extender los brazos. Vuelve a girar las palmas hacia delante en la parte inferior y repite las repeticiones deseadas.','strength','isolation','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000291','back-extension','Extensión de Espalda','Un movimiento de aislamiento que trabaja los erectores espinales de la zona lumbar en un banco de hiperextensión.','Acuéstate boca abajo en un banco de hiperextensión con las caderas en el borde del pad. Baja el torso hacia el suelo. Sube el torso hasta que el cuerpo quede recto. Repite.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000292','band-assisted-pull-ups','Dominadas Asistidas con Banda','Una dominada con banda elástica enganchada a la barra que reduce el peso corporal a vencer en cada repetición.','Engancha una banda elástica en la barra de dominadas e introduce un pie en ella. Agarra la barra con las palmas mirando hacia afuera, a la anchura de los hombros. Tira del pecho hacia la barra impulsando los codos hacia abajo. Bájate de forma controlada hasta quedar colgado con los brazos extendidos. Repite el número de repeticiones deseado.','strength','compound','beginner',null,false,true,'resistance_band'),
  ('30000000-0000-4000-8000-000000000293','banded-good-morning','Buenos Días con Banda','Un hip-hinge con banda elástica sobre la espalda alta, que trabaja isquiotibiales y glúteos.','Pisa una banda elástica con ambos pies y pásala por la nuca. Coloca los pies a la anchura de las caderas, ligera flexión de rodillas. Flexiona desde la cadera empujándola atrás, espalda recta. Baja hasta sentir el estiramiento en los isquiotibiales. Empuja las caderas adelante para volver a la posición inicial.','strength','compound','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000294','banded-hip-thrust','Empuje de Cadera con Banda','Este ejercicio utiliza una banda de bucle para aumentar la activación de los glúteos durante un empuje de cadera, trabajando eficazmente el glúteo mayor, los isquiotibiales y el glúteo medio para mejorar la fuerza de la parte inferior del cuerpo.','Coloca una banda de bucle justo por encima de tus rodillas y siéntate en el suelo con la parte superior de tu espalda contra un banco. Dobla las rodillas, apoya los pies al ancho de las caderas y posiciona la banda para crear tensión. Impúlsate a través de los talones, extiende las caderas y levanta los glúteos del suelo hasta que tu cuerpo forme una línea recta. Aprieta los glúteos con fuerza en la parte superior, asegurándote de empujar las rodillas hacia afuera contra la banda. Baja lentamente las caderas a la posición inicial con control.','strength','compound','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000295','banded-romanian-deadlift','Peso Muerto Rumano con Banda','Un peso muerto rumano con banda elástica, ideal para calentar y aprender el patrón de hip-hinge.','Pisa una banda elástica con ambos pies y agarra el extremo superior. Coloca los pies a la anchura de las caderas, ligera flexión de rodillas. Flexiona desde la cadera, deslizando las manos por las piernas. Baja hasta sentir el estiramiento en los isquiotibiales. Empuja las caderas adelante para volver a la posición inicial.','strength','compound','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000296','banded-seated-hip-abduction','Abducción de Cadera Sentado con Banda','Este ejercicio de aislamiento trabaja el glúteo medio y mayor al rotar externamente las caderas contra la resistencia de una banda mientras estás sentado.','Siéntate en un banco o silla con una banda elástica alrededor de tus rodillas. Mantén los pies apoyados en el suelo, separados al ancho de tus caderas, y conserva una postura erguida. Empuja tus rodillas hacia afuera contra la banda, activando tus glúteos. Sostén la contracción máxima brevemente, luego regresa lentamente tus rodillas a la posición inicial. Controla el movimiento a lo largo de todo el rango de movimiento.','strength','isolation','beginner',null,false,true,'loop_band'),
  ('30000000-0000-4000-8000-000000000297','bench-dips','Fondos en Banco','Un ejercicio de fondos apoyado en un banco que trabaja principalmente el tríceps con el propio peso corporal.','Siéntate en un banco y coloca las manos en el borde junto a las caderas. Desliza las caderas fuera del banco con las piernas extendidas. Baja el cuerpo flexionando los codos hasta 90 grados. Empuja con las palmas para volver a la posición inicial. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000298','bench-leg-pull-in','Encogimiento de Piernas en Banco','Un ejercicio de core en decúbito supino sobre un banco plano que trabaja el recto abdominal llevando las rodillas hacia el pecho.','Túmbate boca arriba sobre un banco plano y agárrate a los lados por encima de la cabeza. Extiende las piernas rectas con los talones justo por encima de la superficie del banco. Lleva las rodillas hacia el pecho levantando ligeramente las caderas del banco. Devuelve las piernas a la posición extendida de forma controlada sin apoyar los talones. Repite el número de repeticiones indicado.','strength','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000299','box-squat','Sentadilla en Caja','Una sentadilla realizada hasta una caja o banco, que fija la profundidad y enseña a sentarse hacia atrás en las caderas.','Ponte de pie frente a una caja o banco, con los pies al ancho de los hombros y los brazos extendidos hacia adelante para el equilibrio. Empuja las caderas hacia atrás y flexiona las rodillas, sentándote hacia la caja en lugar de bajar en línea recta. Toca la caja ligeramente con los glúteos sin dejarte caer sobre ella. Empuja con los pies para volver a ponerte de pie, apretando los glúteos arriba. Repite las repeticiones deseadas.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000300','bulgarian-split-squat','Sentadilla Búlgara','Una variante de sentadilla unilateral con el pie trasero elevado.','Colócate de pie frente a un banco y apoya un pie detrás sobre el banco. Sujeta mancuernas a los lados. Baja el cuerpo hasta que el muslo delantero quede paralelo al suelo. Empuja con el talón delantero para volver a la posición de pie. Repite en ambos lados.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000301','camel-pose','Postura del Camello','Una extensión de rodillas que abre la parte frontal de las caderas, el abdomen y el pecho, con las manos apoyadas en los talones o en la zona lumbar.','Arrodíllate con las rodillas a la anchura de las caderas y las caderas alineadas sobre ellas. Coloca las manos en la parte posterior de la pelvis con los dedos hacia abajo y eleva el pecho. Empuja las caderas hacia delante y arquéate hacia atrás, buscando los talones si la posición sigue cómoda. Mantén la postura durante el tiempo indicado, con el cuello en línea con la columna. Devuelve las manos a la pelvis y sube liderando con el pecho.','stretching','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000302','captains-chair-knee-raise','Elevación de Rodillas en Silla Romana','Un ejercicio de peso corporal en silla romana que trabaja el abdomen bajo y los flexores de cadera.','Colócate en la silla romana con la espalda plana contra el respaldo y los antebrazos en los apoyos. Deja las piernas colgando rectas hacia abajo. Activa el core y sube las rodillas hacia el pecho. Mantén brevemente arriba, luego baja despacio a la posición inicial. Repite el número de repeticiones deseado.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000303','captains-chair-leg-raise','Elevación de Piernas en Silla Romana','Un ejercicio de peso corporal en silla romana para el abdomen bajo con piernas rectas, de mayor dificultad.','Colócate en la silla romana con la espalda plana contra el respaldo y los antebrazos en los apoyos. Deja las piernas colgando rectas hacia abajo. Con las piernas rectas, súbelas hasta la horizontal o más arriba. Mantén brevemente arriba, luego baja despacio. Repite el número de repeticiones deseado.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000304','chest-supported-db-row','Remo con Mancuernas con Apoyo en el Pecho','Un remo con mancuernas con apoyo en el pecho para eliminar la tensión en la zona lumbar y aislar los músculos de la espalda.','Túmbate boca abajo en un banco inclinado con las mancuernas colgando por debajo. Rema las mancuernas hacia los lados. Aprieta en la parte superior y baja. Repite.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000305','chest-supported-dumbbell-shrug','Encogimiento de Hombros con Mancuernas y Apoyo en el Pecho','Un encogimiento de hombros boca abajo en un banco inclinado, donde el apoyo del pecho aísla el trapecio y elimina el impulso.','Ajusta un banco inclinado a unos 30 grados. Túmbate boca abajo en el banco sujetando mancuernas con los brazos extendidos. Encoge los hombros hacia arriba y hacia atrás en dirección a las orejas. Aprieta el trapecio superior en la parte superior. Baja de forma controlada y repite.','strength','isolation','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000306','chest-supported-kettlebell-row','Remo con Kettlebell Apoyado en el Pecho','Este ejercicio trabaja los músculos de tu espalda, principalmente el dorsal ancho y los romboides, remando con una kettlebell en cada mano hacia las caderas mientras el torso está apoyado en un banco inclinado.','Acuéstate boca abajo en un banco inclinado, dejando que tus brazos cuelguen libremente con una kettlebell en cada mano. Contrae tu abdomen y retrae tus escápulas. Tira de las kettlebells hacia tus caderas, apretando tus escápulas. Haz una breve pausa en la parte superior, sintiendo la contracción en tu espalda. Baja lentamente las kettlebells a la posición inicial con control.','strength','compound','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000307','close-grip-db-bench-press','Press de Banca con Mancuernas y Agarre Cerrado','Un press de banca con mancuernas sostenidas juntas para aumentar la participación de los tríceps.','Túmbate en un banco plano y sostén dos mancuernas juntas sobre el pecho. Bájalas hasta el pecho manteniendo los codos cerca. Empuja hacia arriba. Repite.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000308','concentration-curl','Curl de Concentración','Un curl de aislamiento realizado sentado para la máxima contracción del bíceps.','Siéntate en un banco con las piernas separadas y sujeta una mancuerna en una mano. Apoya el codo en la cara interna del muslo. Sube la mancuerna hacia el hombro. Baja con control. Repite en ambos lados.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000309','db-bench-press','Press de Banca con Mancuernas','Un ejercicio compuesto de pecho con mancuernas que permite mayor rango de movimiento que el press de banca con barra.','Túmbate en un banco plano sosteniendo una mancuerna en cada mano a la altura del pecho. Empuja las mancuernas hacia arriba hasta extender completamente los brazos. Bájalas lentamente hasta la posición inicial. Repite.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000310','db-fly','Aperturas con Mancuernas','Un ejercicio de aislamiento que estira y contrae el pectoral a través de un amplio arco de movimiento.','Túmbate en un banco con las mancuernas sobre el pecho y las palmas mirándose entre sí. Con una ligera flexión de codos, baja las mancuernas hacia los lados. Regresa a la posición inicial apretando el pecho. Repite.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000311','db-reverse-wrist-curl','Curl de Muñeca Inverso con Mancuerna','Un curl de muñeca con mancuerna y palma hacia abajo, que entrena los extensores del antebrazo.','Siéntate en un banco con el antebrazo sobre el muslo, palma hacia abajo. Sujeta una mancuerna con la muñeca fuera de la rodilla. Deja caer la muñeca, bajando la mancuerna. Levanta el dorso de la mano hacia el techo extendiendo la muñeca. Baja con control. Repeticiones por lado.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000312','decline-crunch','Crunch Declinado','Un crunch realizado en banco declinado, aumentando el rango de movimiento y la resistencia sobre los abdominales.','Asegura los pies en la parte superior del banco declinado. Recuéstate con las manos cruzadas sobre el pecho o detrás de la cabeza. Sube contrayendo la columna hacia las rodillas. Aprieta el abdomen en la posición superior. Baja de forma controlada y repite.','strength','isolation','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000313','decline-db-fly','Aperturas con Mancuernas en Banco Declinado','Un movimiento de apertura en banco declinado para enfatizar el pecho inferior.','Túmbate en un banco declinado sosteniendo mancuernas sobre el pecho. Con una ligera flexión de codos, baja las mancuernas ampliamente hacia los lados. Aprieta el pecho para subirlas de nuevo. Repite.','strength','isolation','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000314','donkey-calf-raise','Elevación de Pantorrilla a la Burra','Una elevación de pantorrilla inclinada que maximiza el estiramiento al flexionar las caderas.','Flexiona las caderas y apoya los antebrazos sobre un banco. Coloca las puntas de los pies en una plataforma elevada, talones al aire. Baja los talones por debajo de la plataforma para un estiramiento completo. Empuja arriba sobre las puntas tanto como puedas, contrayendo las pantorrillas. Baja con control hasta el estiramiento profundo.','strength','isolation','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000315','downward-dog-pedal','Pedaleo en Perro Boca Abajo','Un calentamiento dentro del perro boca abajo: las rodillas se flexionan alternando, de modo que cada talón presiona hacia el suelo por turnos y la pantorrilla y el tobillo reciben un estiramiento en movimiento en lugar de un mantenimiento estático.','Colócate en perro boca abajo con las manos a la anchura de los hombros y las caderas altas. Flexiona una rodilla y deja que ese talón se eleve mientras el talón contrario presiona hacia el suelo. Cambia de lado con fluidez, como pedaleando, manteniendo las caderas altas todo el tiempo. Presiona las manos por igual para que los hombros se mantengan estables. Sigue alternando las veces o el tiempo indicados.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000316','dumbbell-hip-thrust','Empuje de Cadera con Mancuerna','El Empuje de Cadera con Mancuerna es un ejercicio compuesto muy eficaz para construir glúteos y isquiotibiales fuertes, realizado empujando las caderas hacia arriba con una mancuerna sobre la pelvis.','Siéntate en el suelo con la parte superior de la espalda contra un banco, rodillas flexionadas, pies planos y una mancuerna sobre tus caderas. Contrae tu abdomen y empuja a través de tus talones, levantando las caderas del suelo hasta que tu cuerpo forme una línea recta de hombros a rodillas. Aprieta tus glúteos con fuerza en la parte superior del movimiento, asegurando una extensión completa de la cadera. Baja lentamente tus caderas a la posición inicial con control, manteniendo la tensión. Repite el ejercicio por el número deseado de repeticiones.','strength','compound','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000317','dumbbell-wrist-curl','Curl de Muñeca con Mancuerna','Un curl de muñeca con mancuerna que aísla los flexores del antebrazo y trabaja ambos brazos por separado.','Siéntate en un banco con el antebrazo sobre el muslo, palma hacia arriba. Sujeta una mancuerna con la muñeca fuera de la rodilla. Deja que la mancuerna ruede hasta las puntas de los dedos. Sube la mancuerna flexionando la muñeca. Baja con control. Repeticiones por lado.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000318','jefferson-curl','Jefferson curl','Un ejercicio de flexión espinal con carga: de pie y con un peso ligero, redondeas la columna vértebra a vértebra y la vuelves a apilar, desarrollando control segmentario y flexibilidad de isquiotibiales y erectores bajo carga.','Ponte de pie sujetando una mancuerna ligera con los brazos estirados, pies aproximadamente al ancho de las caderas. Mete la barbilla y empieza a redondear la columna desde arriba, vértebra a vértebra. Baja despacio dejando colgar el peso y manteniendo las piernas casi rectas. Llega abajo con la espalda totalmente redondeada y un estiramiento en los isquiotibiales. Invierte el movimiento, reapilando la columna de abajo hacia arriba hasta ponerte de pie.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000319','kettlebell-concentration-curl','Curl de concentración con kettlebell','Un ejercicio de aislamiento de bíceps a una mano, sentado: el codo se apoya contra la cara interna del muslo mientras se curla una kettlebell, manteniendo el brazo quieto para que el bíceps haga todo el trabajo.','Siéntate en un banco con los pies bien separados, sujetando una kettlebell con una mano. Apoya la parte posterior del brazo contra la cara interna del muslo y deja colgar la kettlebell. Curla la kettlebell hacia el hombro, manteniendo el codo fijo contra la pierna. Contrae el bíceps arriba y luego baja despacio y de forma controlada. Termina todas las repeticiones de un lado y cambia de brazo.','strength','isolation','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000320','kettlebell-hip-thrust','Empuje de Cadera con Kettlebell','Este ejercicio trabaja eficazmente el glúteo mayor y los isquiotibiales, utilizando una kettlebell para añadir resistencia y lograr una potente extensión de cadera y desarrollo de glúteos.','Siéntate en el suelo con la parte superior de tu espalda apoyada en un banco, las rodillas flexionadas y los pies planos. Coloca una kettlebell sobre tus caderas, sujetándola firmemente con ambas manos. Impúlsate a través de tus talones, levantando tus caderas del suelo hasta que tu cuerpo forme una línea recta desde los hombros hasta las rodillas. Contrae tus glúteos con fuerza en la parte superior del movimiento. Baja lentamente tus caderas de vuelta a la posición inicial con control.','strength','compound','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000321','kettlebell-reverse-wrist-curl','Curl de Muñeca Inverso con Kettlebell','Un curl de muñeca inverso unilateral con kettlebell, que entrena los extensores del antebrazo.','Siéntate en un banco con el antebrazo sobre el muslo, palma hacia abajo. Sujeta una kettlebell por el asa, muñeca fuera de la rodilla. Deja caer la muñeca, bajando la kettlebell. Levanta el dorso de la mano extendiendo la muñeca. Baja con control. Repeticiones por lado.','strength','isolation','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000322','kettlebell-svend-press','Press Svend con Kettlebells','Un ejercicio de pecho de pie presionando dos kettlebells unidas por las bolas, donde la presión hacia dentro mantiene los pectorales en tensión constante.','De pie, junta dos kettlebells por las bolas a la altura del pecho. Mantén las kettlebells horizontales — bolas tocándose, asas hacia afuera. Empuja las kettlebells al frente hasta que los brazos queden casi estirados. Tíralas de regreso al pecho con control. Repite el número de repeticiones indicado.','strength','isolation','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000323','kettlebell-wrist-curl','Curl de Muñeca con Kettlebell','Un curl de muñeca unilateral con kettlebell — el peso descentrado añade un reto extra al agarre.','Siéntate en un banco con el antebrazo sobre el muslo, palma hacia arriba. Sujeta una kettlebell por el asa, muñeca fuera de la rodilla. Deja que la kettlebell rote hacia las puntas de los dedos. Súbela flexionando la muñeca, controlando el peso descentrado. Baja con control. Repeticiones por lado.','strength','isolation','beginner',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000324','lateral-leg-swing','Balanceo Lateral de Pierna','Un ejercicio dinámico de movilidad de cadera en el que una pierna cruza por delante del cuerpo y después se balancea hacia el lado mientras la pierna de apoyo y el tronco se mantienen controlados.','Ponte erguido, activa el tronco y usa un apoyo estable si lo necesitas. Lleva el peso a una pierna y eleva ligeramente el otro pie del suelo. Balancea la pierna libre cruzándola por delante del cuerpo. Invierte el movimiento y llévala hacia el lado dentro de un rango cómodo. Continúa con fluidez y después cambia de pierna.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000325','leg-swing-front-to-back','Balanceo de Pierna Adelante y Atrás','Un ejercicio dinámico de movilidad de cadera que balancea una pierna recta o ligeramente flexionada hacia delante y hacia atrás mientras el lado de apoyo estabiliza la pelvis.','Ponte erguido junto a un apoyo estable y lleva el peso a la pierna interior. Activa el tronco y eleva ligeramente el pie exterior del suelo. Balancea la pierna libre hacia delante dentro de un rango cómodo. Déjala viajar hacia atrás sin arquear la zona lumbar. Continúa con fluidez y después repite con la otra pierna.','stretching','isolation','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000326','lying-leg-raise','Elevación de Piernas Acostado','Un ejercicio de suelo para el abdomen bajo y los flexores de cadera que consiste en elevar las piernas rectas desde posición supina.','Túmbate boca arriba con las piernas rectas y las manos bajo la zona lumbar o sujetando una superficie estable detrás de la cabeza. Con las piernas juntas y el core activado, eleva las piernas hasta la vertical. Pausa brevemente arriba. Baja las piernas despacio hacia el suelo sin llegar a apoyarlas. Repite el número de repeticiones deseado.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000327','one-arm-kettlebell-row','Remo con Pesa Rusa a Un Brazo','Un remo unilateral con pesa rusa y apoyo en banco, que fortalece el dorsal ancho y los romboides de cada lado.','Apoya una mano y una rodilla sobre un banco para sujetarte. Sostén una pesa rusa en la mano contraria con el brazo extendido. Jala la pesa rusa hacia la cadera llevando el codo hacia atrás. Aprieta la espalda en la parte superior del movimiento. Baja la pesa rusa con control. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'kettlebell'),
  ('30000000-0000-4000-8000-000000000328','reverse-tabletop-hip-pulses','Pulsos de Cadera en Mesa Invertida','Pulsos de glúteo desde la mesa invertida: los brazos permanecen estirados y solo las caderas bajan y suben, de modo que el trabajo se queda en el glúteo y no en el tríceps.','Siéntate con las rodillas flexionadas, los pies apoyados y las manos en el suelo detrás de ti. Empuja con manos y pies y eleva las caderas hasta que el tronco quede a la altura de las rodillas. Con los codos estirados, baja las caderas unos centímetros. Aprieta los glúteos para volver a subirlas al nivel. Pulsa las veces indicadas y baja.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000329','reverse-tabletop-hold','Mesa Invertida Isométrica','Una mesa invertida estática: rodillas flexionadas, manos bajo los hombros por detrás del cuerpo, caderas elevadas a la altura de las rodillas y sostenidas, de modo que los glúteos y toda la parte posterior del tronco trabajan de forma isométrica.','Siéntate con las rodillas flexionadas, los pies apoyados y las manos en el suelo detrás de ti, con los dedos hacia los talones. Empuja con manos y pies y eleva las caderas hasta que el tronco quede a la altura de las rodillas. Abre el pecho, aleja los hombros de las orejas y mira al frente. Mantén la posición durante el tiempo indicado con las caderas altas. Baja las caderas de forma controlada para terminar.','strength','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000330','savasana','Postura del Cadáver','El descanso final de una práctica: tumbado boca arriba con el cuerpo completamente pasivo, dejando que los efectos de la sesión se asienten.','Túmbate boca arriba con las piernas cómodamente separadas y los pies cayendo hacia fuera. Deja los brazos algo separados del cuerpo con las palmas hacia arriba. Permite que todo el cuerpo se ablande contra el suelo, incluidos la mandíbula, los ojos y las manos. Permanece durante el tiempo indicado, respirando con naturalidad y sin controlar la respiración. Flexiona las rodillas y rueda hacia un lado antes de incorporarte despacio.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000331','seated-db-press','Press de Hombro con Mancuernas Sentado','Un movimiento de press sentado para los hombros usando mancuernas.','Siéntate en un banco con respaldo sosteniendo mancuernas a la altura de los hombros. Empuja las mancuernas sobre la cabeza hasta extender completamente los brazos. Baja las mancuernas de vuelta a la altura de los hombros. Repite.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000332','seated-dumbbell-curl','Curl con Mancuernas Sentado','Un curl de bíceps sentado con mancuernas, donde la posición sentada y erguida elimina el impulso para una técnica más estricta.','Siéntate en un banco con una mancuerna en cada mano. Deja los brazos colgando a los lados con las palmas hacia adelante. Sube ambas mancuernas hacia los hombros flexionando los bíceps. Aprieta en la parte superior del movimiento. Baja las mancuernas con control. Repite el número deseado de repeticiones.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000333','seated-dumbbell-lateral-raise','Elevación Lateral con Mancuerna Sentado','Un ejercicio de aislamiento sentado que levanta las mancuernas hacia los lados, trabajando los deltoides laterales sin impulso de piernas.','Siéntate en un banco con una mancuerna en cada mano a los lados. Mantén la espalda erguida y el core contraído. Eleva ambas mancuernas hacia los lados hasta la altura de los hombros. Mantén una ligera flexión en los codos. Baja las mancuernas con control. Repite el número de repeticiones deseado.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000334','seated-dumbbell-tricep-extension','Extensión de Tríceps con Mancuerna Sentado','Una extensión por encima de la cabeza sentado que baja la mancuerna detrás de la cabeza, estirando y trabajando los tríceps.','Siéntate en un banco con una mancuerna sostenida sobre la cabeza con ambas manos. Mantén los brazos superiores verticales junto a las orejas. Baja la mancuerna detrás de la cabeza flexionando los codos. Extiende los brazos para empujar la mancuerna de vuelta arriba. Aprieta los tríceps en la parte superior. Repite el número de repeticiones deseado.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000335','side-lying-lateral-raise','Elevación Lateral Tumbado de Lado','Un ejercicio de aislamiento del deltoides lateral con mancuerna en posición lateral sobre un banco plano, que proporciona tensión constante sin impulso.','Túmbate de lado sobre un banco plano usando el brazo inferior para apoyar la cabeza o sujetar el borde del banco. Sujeta una mancuerna con la mano superior con el brazo descansando a lo largo del costado. Con el codo ligeramente flexionado, eleva la mancuerna hasta que el brazo quede perpendicular al suelo. Pausa brevemente arriba, luego baja la mancuerna despacio hasta el costado. Completa todas las repeticiones en un lado antes de cambiar.','strength','isolation','beginner',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000336','side-plank-leg-lift','Plancha Lateral con Elevación de Pierna','Una plancha lateral con elevación de la pierna superior, que combina trabajo de core lateral con abducción de cadera.','Túmbate de lado con el antebrazo en el suelo y el codo bajo el hombro. Coloca un pie sobre el otro y eleva las caderas hasta una plancha lateral. Desde esta plancha lateral estable, sube la pierna de arriba recta hacia el techo. Baja la pierna de forma controlada sin dejar caer las caderas. Completa las repeticiones de un lado y luego cambia.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000337','single-arm-db-row','Remo con Mancuerna a Un Brazo','Un ejercicio de espalda unilateral con mancuerna para un desarrollo equilibrado.','Coloca una rodilla y una mano en un banco como apoyo. Sostén una mancuerna en la otra mano con el brazo extendido. Tira de la mancuerna hacia la cadera apretando el omóplato. Baja la mancuerna con control. Repite de ambos lados.','strength','compound','intermediate',null,false,true,'dumbbell'),
  ('30000000-0000-4000-8000-000000000338','step-ups','Step Ups','Una subida a un cajón o banco con una pierna que entrena cuádriceps y glúteos de forma funcional.','Párate frente a una caja o banco resistente. Coloca un pie completamente sobre la superficie de la caja. Empuja a través de ese talón para subir el cuerpo a la caja. Sube el pie de atrás para quedar completamente sobre la caja. Baja con el mismo pie que subió primero. Alterna piernas o completa todas las repeticiones de un lado antes de cambiar.','strength','compound','intermediate',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000339','torso-twists','Giros de Torso','Un calentamiento rotacional de pie que gira la caja torácica de un lado a otro mientras la pelvis permanece relativamente estable, movilizando la columna torácica y el tronco.','Ponte de pie con los pies separados al ancho de los hombros y las rodillas ligeramente flexionadas. Activa suavemente el tronco y junta las manos frente al pecho. Gira la caja torácica hacia un lado sin desplazar los pies. Vuelve al centro y gira hacia el otro lado. Sigue alternando con fluidez dentro de un rango cómodo.','stretching','compound','beginner',null,false,true,'no_equipment'),
  ('30000000-0000-4000-8000-000000000340','walking','Caminar','Marcha natural sobre terreno llano, manteniendo siempre un pie en contacto con el suelo, lo que la convierte en la forma de menor impacto de acumular trabajo aeróbico.','Ponte erguido, con el peso sobre la parte media de los pies y los hombros relajados, sin llevarlos hacia atrás. Da un paso al frente y apoya primero el talón, luego rueda sobre el pie y empuja con la almohadilla y los dedos. Mantén al menos un pie en el suelo en todo momento — en cuanto ambos se despegan estás corriendo, no caminando. Deja que los brazos oscilen con naturalidad desde el hombro, brazo contrario a pierna contraria, con los codos ligeramente flexionados. Mira al frente en lugar de a los pies y respira con un ritmo constante y sostenible. Continúa el tiempo o la distancia deseados, eligiendo un ritmo al que todavía podrías mantener una conversación.','cardio','compound','beginner',null,false,true,'no_equipment')
  ,('30000000-0000-4000-8000-000000000341','double-kettlebell-bicep-curl','Curl de Bíceps con Dos Pesas Rusas','Un curl de bíceps de pie con una pesa rusa en cada mano, sujeta por el asa. La masa descentrada en la parte inferior de la pesa añade un ligero reto de agarre y estabilidad.','Ponte de pie sujetando una pesa rusa en cada mano por el asa, con las palmas mirando hacia adelante. Mantén los codos pegados a los costados y las pesas colgando a lo largo de los brazos. Sube ambas pesas rusas hacia los hombros flexionando los codos. Aprieta los bíceps en la parte superior, luego baja de forma controlada hasta la posición inicial. Repite el número de repeticiones recomendado.','strength','isolation','beginner',null,false,true,'kettlebell');

-- Keep the underscore slugs used by the original planner wherever a legacy
-- exercise has the same RepDB slug with hyphens.
update repdb_catalogue_seed seed
set slug = replace(seed.slug, '-', '_')
where exists (select 1 from public.exercises legacy where legacy.slug = replace(seed.slug, '-', '_'));

insert into public.exercises (id,slug,name,description,instructions,category,movement_pattern,difficulty,impact_level,is_outdoor,is_active)
select id,slug,name,description,instructions,category,movement_pattern,difficulty,impact_level,is_outdoor,is_active from repdb_catalogue_seed
on conflict (slug) do update set name=excluded.name,description=excluded.description,instructions=excluded.instructions,category=excluded.category,movement_pattern=excluded.movement_pattern,difficulty=excluded.difficulty,impact_level=excluded.impact_level,is_outdoor=excluded.is_outdoor,is_active=true;

-- Preserve the original English planner label for the legacy compatibility slug.
update public.exercises set name = 'Bodyweight squat' where slug = 'bodyweight_squat';

-- Every catalogue row has a minimal executable prescription. Timed movements
-- can use the duration, while rep-based movements have three default sets.
update public.exercises
set default_sets = coalesce(default_sets, 3),
    default_reps = coalesce(default_reps, '8–12'),
    default_duration_seconds = coalesce(default_duration_seconds, 30)
where slug in (select slug from repdb_catalogue_seed);

insert into public.exercise_equipment (exercise_id,equipment_id,requirement_group)
select e.id,eq.id,1 from public.exercises e join repdb_catalogue_seed s on s.slug=e.slug join public.equipment eq on eq.slug=s.equipment_slug on conflict do nothing;
