-- Remove legacy rows where no completed exercise history depends on them.
delete from public.exercise_media where exercise_id in (select id from public.exercises where slug not in (select slug from repdb_catalogue_seed));
delete from public.exercise_equipment where exercise_id in (select id from public.exercises where slug not in (select slug from repdb_catalogue_seed));
delete from public.exercise_muscles where exercise_id in (select id from public.exercises where slug not in (select slug from repdb_catalogue_seed));
delete from public.workout_template_blocks where exercise_id in (select id from public.exercises where slug not in (select slug from repdb_catalogue_seed));
delete from public.exercises old where old.slug not in (select slug from repdb_catalogue_seed) and not exists (select 1 from public.exercise_sessions history where history.exercise_id=old.id);
update public.exercises set is_active=false where slug not in (select slug from repdb_catalogue_seed);
